-- APP-20261003-02. Operator-only, explicit historical content migration.
-- No automatic backfill, no student state writes, no trigger/GUC bypass.
create table private.historical_question_migrations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check(kind in ('assignment','quiz','exam-use')),
  row_id uuid not null,
  assignment_id uuid not null references public.assignments(id),
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  body_sha256 text not null check(body_sha256 ~ '^[a-f0-9]{64}$'),
  identity_sha256 text not null check(identity_sha256 ~ '^[a-f0-9]{64}$'),
  content_version_id uuid not null references private.vocabulary_question_content_versions(id),
  meaning jsonb not null,
  state text not null default 'prepared' check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp(),
  unique(kind,row_id,original_sha256)
);
create table private.historical_question_migration_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  result jsonb not null,
  created_at timestamptz not null default clock_timestamp()
);
create table private.historical_question_write_permits (
  backend_pid integer not null,
  transaction_id bigint not null,
  relation_id oid not null,
  before_sha256 text not null,
  after_sha256 text not null,
  primary key(backend_pid,transaction_id,relation_id,before_sha256)
);
alter table private.historical_question_migrations enable row level security;
alter table private.historical_question_migration_receipts enable row level security;
alter table private.historical_question_write_permits enable row level security;
revoke all on private.historical_question_migrations,private.historical_question_migration_receipts,
  private.historical_question_write_permits from public,anon,authenticated,service_role;
create trigger historical_question_receipt_immutable before update or delete on private.historical_question_migration_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

create function private.historical_question_spec_v1(p_kind text) returns jsonb
language plpgsql immutable set search_path='' as $$
begin
  if p_kind='assignment' then return jsonb_build_object('relation','public.assignment_questions','key','id','body',array[
    'prompt','choices','headword_snapshot','primary_meaning_snapshot','correct_answer_snapshot','provenance',
    'composition_pronunciation_snapshot','notebook_pronunciation_snapshot']);
  elsif p_kind='quiz' then return jsonb_build_object('relation','public.quiz_questions','key','id','body',array['prompt','choices']);
  elsif p_kind='exam-use' then return jsonb_build_object('relation','public.assignment_question_exam_use_snapshot','key','assignment_question_id','body',array[
    'headword_snapshot','primary_meaning_snapshot','display_pronunciation_ko_snapshot','pronunciation_snapshot','choice_dictionary_snapshots']);
  end if;
  raise exception 'historical_question_kind_invalid' using errcode='22023';
end $$;

create function private.historical_question_document_v1(p_kind text,p_row jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare spec jsonb:=private.historical_question_spec_v1(p_kind); fields text[]; identity_doc jsonb;
begin
  select array_agg(value) into fields from jsonb_array_elements_text(spec->'body');
  if p_kind='quiz' then
    identity_doc:=private.vocabulary_question_json_fields_v1(p_row,array[
      'id','attempt_id','assignment_question_id','vocab_entry_id','order_index','direction','correct_choice_index']);
  else identity_doc:=p_row-fields-'content_version_id'; end if;
  return jsonb_build_object('kind',p_kind,'identity',identity_doc,'body',private.vocabulary_question_json_fields_v1(p_row,fields),
    'contentVersionId',p_row->'content_version_id');
end $$;

create function private.historical_question_row_v1(p_kind text,p_row_id uuid,p_lock boolean default false) returns jsonb
language plpgsql set search_path='' as $$
declare spec jsonb:=private.historical_question_spec_v1(p_kind); answer jsonb;
begin
  execute format('select to_jsonb(q) from %s q where %I=$1%s',
    (spec->>'relation')::regclass,spec->>'key',case when p_lock then ' for update' else '' end) into answer using p_row_id;
  if answer is null then raise exception 'historical_question_missing' using errcode='P0002'; end if;
  return answer;
end $$;

create function private.historical_question_assignment_v1(p_kind text,p_row jsonb) returns uuid
language plpgsql stable set search_path='' as $$
declare answer uuid;
begin
  if p_kind in('assignment','exam-use') then answer:=(p_row->>'assignment_id')::uuid;
  elsif p_kind='quiz' then select assignment_id into answer from public.quiz_attempts where id=(p_row->>'attempt_id')::uuid;
  end if;
  if answer is null then raise exception 'historical_question_assignment_missing' using errcode='23503'; end if;
  return answer;
end $$;

create function private.historical_question_participants_v1(p_assignment_id uuid) returns uuid[]
language sql stable set search_path='' as $$
  select coalesce(array_agg(student_id order by student_id),'{}'::uuid[]) from (
    select student_id from public.assignment_students where assignment_id=p_assignment_id
    union select student_id from public.quiz_attempts where assignment_id=p_assignment_id
    union select student_id from private.quiz_attempt_preparations where assignment_id=p_assignment_id
  ) students;
$$;

create function private.lock_historical_question_assignment_v1(p_assignment_id uuid,p_compact boolean) returns void
language plpgsql set search_path='' as $$
declare participants uuid[]; settings public.assignments; student_id uuid;
begin
  participants:=private.historical_question_participants_v1(p_assignment_id);
  foreach student_id in array participants loop perform private.lock_vocabulary_student_v1(student_id); end loop;
  select * into settings from public.assignments where id=p_assignment_id for update;
  if settings.id is null then raise exception 'historical_question_assignment_missing' using errcode='P0002'; end if;
  if participants is distinct from private.historical_question_participants_v1(p_assignment_id)
    then raise exception 'historical_question_participants_changed' using errcode='40001'; end if;
  perform 1 from public.quiz_attempts where assignment_id=p_assignment_id order by id for update;
  perform 1 from private.quiz_attempt_preparations where assignment_id=p_assignment_id order by id for update;
  if not p_compact then return; end if;
  if not coalesce(settings.status='closed' or settings.deleted_at is not null
      or (isfinite(settings.available_until) and settings.available_until<clock_timestamp()),false)
    then raise exception 'historical_question_assignment_open' using errcode='55000'; end if;
  if exists(select 1 from public.quiz_attempts where assignment_id=p_assignment_id
      and (status='in_progress' or completed_at is null or phase in('review','retry')))
    then raise exception 'historical_question_attempt_pending' using errcode='55000'; end if;
  -- A server cannot infer whether a device still holds answers. Exclude every
  -- local protocol run rather than guessing from elapsed time or a summary.
  if exists(select 1 from private.local_quiz_runs r join public.quiz_attempts a on a.id=r.attempt_id where a.assignment_id=p_assignment_id)
    or exists(select 1 from private.local_quiz_preparations l join private.quiz_attempt_preparations p on p.id=l.preparation_id where p.assignment_id=p_assignment_id)
    then raise exception 'historical_question_device_bound' using errcode='55000'; end if;
  if exists(select 1 from private.vocabulary_result_policies r join public.quiz_attempts a on a.id=r.attempt_id where a.assignment_id=p_assignment_id)
    then raise exception 'historical_question_result_policy' using errcode='55000'; end if;
  if exists(select 1 from private.quiz_attempt_preparations where assignment_id=p_assignment_id and begun_id is null)
    then raise exception 'historical_question_preparation_pending' using errcode='55000'; end if;
  if exists(select 1 from public.assignment_questions where assignment_id=p_assignment_id and provenance_status='notebook_snapshot_v1')
    then raise exception 'historical_question_personal_source' using errcode='55000'; end if;
end $$;

create function private.historical_question_meaning_v1(p_kind text,p_row jsonb) returns jsonb
language plpgsql stable set search_path='' as $$
begin
  if p_kind='quiz' then return private.quiz_vocabulary_meaning_v1((p_row->>'id')::uuid); end if;
  return private.assignment_vocabulary_meaning_v1((p_row->>(case when p_kind='assignment' then 'id' else 'assignment_question_id' end))::uuid);
end $$;

create function private.historical_question_resolve_v1(p_kind text,p_row jsonb) returns jsonb
language plpgsql stable set search_path='' as $$
begin
  if p_kind='assignment' then return to_jsonb(private.resolve_assignment_question_content_v1(jsonb_populate_record(null::public.assignment_questions,p_row)));
  elsif p_kind='quiz' then return to_jsonb(private.resolve_quiz_question_content_v1(jsonb_populate_record(null::public.quiz_questions,p_row)));
  elsif p_kind='exam-use' then return to_jsonb(private.resolve_exam_use_question_content_v1(jsonb_populate_record(null::public.assignment_question_exam_use_snapshot,p_row)));
  end if;
  raise exception 'historical_question_kind_invalid' using errcode='22023';
end $$;

create function private.prepare_historical_question_batch_v1(p_assignment_id uuid,p_kind text,p_row_ids uuid[]) returns jsonb
language plpgsql set search_path='' as $$
declare selected_row_id uuid; original jsonb; document jsonb; resolved jsonb; reference uuid;
  spec jsonb:=private.historical_question_spec_v1(p_kind); candidate private.historical_question_migrations;
  fields text[]; identity_doc jsonb; meaning_doc jsonb; answer jsonb:='[]'; fingerprint text;
begin
  if current_user<>'postgres' then raise exception 'historical_question_operator_required' using errcode='42501'; end if;
  if p_row_ids is null or cardinality(p_row_ids) not between 1 and 100 or array_position(p_row_ids,null) is not null
    or cardinality(p_row_ids)<>(select count(distinct x) from unnest(p_row_ids)x)
    then raise exception 'historical_question_batch_invalid' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(61003,2);
  perform private.lock_historical_question_assignment_v1(p_assignment_id,true);
  select array_agg(value) into fields from jsonb_array_elements_text(spec->'body');
  for selected_row_id in select x from unnest(p_row_ids)x order by x loop
    original:=private.historical_question_row_v1(p_kind,selected_row_id,true);
    if private.historical_question_assignment_v1(p_kind,original) is distinct from p_assignment_id
      then raise exception 'historical_question_assignment_mismatch' using errcode='23514'; end if;
    if original->>'content_version_id' is not null then raise exception 'historical_question_already_referenced' using errcode='55000'; end if;
    document:=private.historical_question_document_v1(p_kind,original);
    fingerprint:=private.reviewed_exam_sha256_v1(document);
    meaning_doc:=private.historical_question_meaning_v1(p_kind,original);
    if p_kind='assignment' then
      perform private.assert_assignment_question_body_v1(jsonb_populate_record(null::public.assignment_questions,original));
      reference:=private.register_assignment_question_content_v1(jsonb_populate_record(null::public.assignment_questions,original));
    elsif p_kind='quiz' then
      reference:=private.register_quiz_question_content_v1(jsonb_populate_record(null::public.quiz_questions,original),p_assignment_id);
    else
      perform private.assert_exam_use_question_body_v1(jsonb_populate_record(null::public.assignment_question_exam_use_snapshot,original));
      reference:=private.register_vocabulary_question_content_v1('exam-use',array[(original->>'dataset_id')::uuid],
        private.exam_use_question_binding_v1(jsonb_populate_record(null::public.assignment_question_exam_use_snapshot,original)),document->'body');
    end if;
    resolved:=private.historical_question_resolve_v1(p_kind,original||jsonb_build_object('content_version_id',reference));
    if private.historical_question_document_v1(p_kind,resolved)-'contentVersionId' is distinct from document-'contentVersionId'
      then raise exception 'historical_question_read_mismatch' using errcode='23514'; end if;
    if p_kind='assignment' and exists(select 1 from public.quiz_questions q where q.assignment_question_id=selected_row_id
      and q.content_version_id is not null and q.content_version_id<>reference)
      then raise exception 'historical_question_dependent_reference_mismatch' using errcode='23514'; end if;
    identity_doc:=document->'identity';
    insert into private.historical_question_migrations(kind,row_id,assignment_id,original_sha256,body_sha256,identity_sha256,content_version_id,meaning)
      values(p_kind,selected_row_id,p_assignment_id,fingerprint,private.reviewed_exam_sha256_v1(document->'body'),
        private.reviewed_exam_sha256_v1(identity_doc),reference,meaning_doc) on conflict(kind,row_id,original_sha256) do nothing;
    select * into strict candidate from private.historical_question_migrations where kind=p_kind and row_id=selected_row_id and original_sha256=fingerprint;
    if candidate.content_version_id<>reference or candidate.meaning is distinct from meaning_doc or candidate.state<>'prepared'
      then raise exception 'historical_question_preparation_conflict' using errcode='40001'; end if;
    answer:=answer||jsonb_build_array(jsonb_build_object('id',candidate.id,'before',document));
  end loop;
  return answer;
end $$;

create function private.keep_historical_question_meaning_v1(p_question_id uuid,p_meaning jsonb) returns void
language plpgsql set search_path='' as $$
declare reference uuid; context_key text; existing jsonb;
begin
  select content_version_id into reference from public.assignment_questions where id=p_question_id;
  if reference is null then return; end if;
  select v.identity into existing from private.assignment_vocabulary_meaning_refs r
    join private.vocabulary_question_meaning_versions v using(content_version_id,context_hash)
    where r.assignment_question_id=p_question_id and r.content_version_id=reference;
  if found then
    if existing is distinct from p_meaning then raise exception 'historical_question_meaning_changed' using errcode='23514'; end if;
    return;
  end if;
  context_key:=private.reviewed_exam_sha256_v1(jsonb_build_array(private.assignment_vocabulary_meaning_context_v1(p_question_id),p_meaning));
  insert into private.vocabulary_question_meaning_versions(content_version_id,context_hash,identity)
    values(reference,context_key,p_meaning) on conflict do nothing;
  select v.identity into existing from private.vocabulary_question_meaning_versions v where v.content_version_id=reference and v.context_hash=context_key;
  if existing is distinct from p_meaning then raise exception 'historical_question_meaning_changed' using errcode='23514'; end if;
  insert into private.assignment_vocabulary_meaning_refs(assignment_question_id,content_version_id,context_hash)
    values(p_question_id,reference,context_key);
end $$;

-- The exception capability is a single exact row image in this transaction.
-- It cannot be enabled through request claims, role names or a custom setting.
create function private.consume_historical_question_permit_v1(p_relation oid,p_before jsonb,p_after jsonb) returns boolean
language sql volatile security definer set search_path='' as $$
  with consumed as(delete from private.historical_question_write_permits
    where backend_pid=pg_backend_pid() and transaction_id=txid_current() and relation_id=p_relation
      and before_sha256=private.reviewed_exam_sha256_v1(p_before) and after_sha256=private.reviewed_exam_sha256_v1(p_after)
    returning true as permitted)
  select coalesce(bool_or(permitted),false) from consumed;
$$;

-- Preserve each current trigger's OID and ordinary path. Only the exact operator
-- update can keep an expanded, verified body alongside its original reference.
do $patch$
declare kind text; signature text; definition text; addition text;
begin
  foreach kind in array array['assignment','quiz','exam-use'] loop
    signature:=case kind when 'assignment' then 'private.freeze_assignment_question_content_v1()'
      when 'quiz' then 'private.freeze_quiz_question_content_v1()' else 'private.freeze_exam_use_question_content_v1()' end;
    definition:=replace(pg_get_functiondef(signature::regprocedure),chr(13),'');
    if (length(definition)-length(replace(definition,E'\nbegin\n','')))/length(E'\nbegin\n')<>1
      then raise exception 'historical_question_trigger_context_changed' using errcode='55000'; end if;
    addition:=format($body$
  if tg_op='UPDATE' and private.consume_historical_question_permit_v1(tg_relid,to_jsonb(old),to_jsonb(new)) then
    if new.content_version_id is null or (old.content_version_id is not null and old.content_version_id<>new.content_version_id)
      then raise exception 'historical_question_reference_changed' using errcode='23514'; end if;
    if exists(select 1 from jsonb_each(private.historical_question_document_v1(%L,to_jsonb(new))->'body') e
      where e.value<>'null'::jsonb and e.value is distinct from
        (private.historical_question_document_v1(%L,private.historical_question_resolve_v1(%L,to_jsonb(new)))->'body')->e.key)
      then raise exception 'historical_question_body_mismatch' using errcode='23514'; end if;
    return new;
  end if;
$body$,kind,kind,kind);
    execute replace(definition,E'\nbegin\n',E'\nbegin\n'||addition);
  end loop;
end;
$patch$;

alter table public.assignment_questions drop constraint assignment_question_content_storage;
alter table public.assignment_questions add constraint assignment_question_content_storage check(
  (content_version_id is null and prompt is not null and choices is not null) or
  (content_version_id is not null and (
    (prompt is null and choices is null and headword_snapshot is null and primary_meaning_snapshot is null
      and correct_answer_snapshot is null and composition_pronunciation_snapshot is null and notebook_pronunciation_snapshot is null
      and (provenance_status='notebook_snapshot_v1' or provenance is null))
    or (prompt is not null and choices is not null))));
alter table public.quiz_questions drop constraint quiz_question_content_storage;
alter table public.quiz_questions add constraint quiz_question_content_storage check(
  (content_version_id is null and prompt is not null and choices is not null) or
  (content_version_id is not null and ((prompt is null and choices is null) or (prompt is not null and choices is not null))));
alter table public.assignment_question_exam_use_snapshot drop constraint exam_use_question_content_storage;
alter table public.assignment_question_exam_use_snapshot add constraint exam_use_question_content_storage check(
  (content_version_id is null and headword_snapshot is not null and primary_meaning_snapshot is not null
    and pronunciation_snapshot is not null and choice_dictionary_snapshots is not null) or
  (content_version_id is not null and (
    (headword_snapshot is null and primary_meaning_snapshot is null and display_pronunciation_ko_snapshot is null
      and pronunciation_snapshot is null and choice_dictionary_snapshots is null) or
    (headword_snapshot is not null and primary_meaning_snapshot is not null and pronunciation_snapshot is not null and choice_dictionary_snapshots is not null))));

create function private.apply_historical_question_batch_v1(p_request_id uuid,p_action text,p_archive_sha256 text,p_rows jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare request_hash text; receipt private.historical_question_migration_receipts; candidate private.historical_question_migrations;
  entry jsonb; original jsonb; before_doc jsonb; current_doc jsonb; changed jsonb; patch jsonb; spec jsonb; fields text[];
  assignment_id uuid; this_assignment uuid; row_count integer; updates integer:=0; assignments text;
  body_doc jsonb; after_doc jsonb; result jsonb; details jsonb:='[]'; actual jsonb; state_value text; referenced boolean;
begin
  if current_user<>'postgres' then raise exception 'historical_question_operator_required' using errcode='42501'; end if;
  if p_request_id is null or p_action is null or p_action not in('compact','restore') or p_archive_sha256 is null
    or p_archive_sha256 !~ '^[a-f0-9]{64}$' or jsonb_typeof(p_rows) is distinct from 'array'
    then raise exception 'historical_question_request_invalid' using errcode='22023'; end if;
  row_count:=jsonb_array_length(p_rows);
  if row_count not between 1 and 100 or octet_length(p_rows::text)>4194304
    or exists(select 1 from jsonb_array_elements(p_rows)e where jsonb_typeof(e) is distinct from 'object'
      or e-array['id','before']<>'{}'::jsonb or e->>'id' is null or jsonb_typeof(e->'before') is distinct from 'object')
    or (select count(distinct (e->>'id')::uuid) from jsonb_array_elements(p_rows)e)<>row_count
    then raise exception 'historical_question_batch_invalid' using errcode='22023'; end if;
  request_hash:=private.reviewed_exam_sha256_v1(jsonb_build_array(1,p_action,p_archive_sha256,p_rows));
  -- Serialize only operator batches. Student traffic uses its existing row locks.
  perform pg_advisory_xact_lock(61003,2);
  select * into receipt from private.historical_question_migration_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'historical_question_request_conflict' using errcode='40001'; end if;
    return receipt.result;
  end if;
  select count(distinct m.assignment_id),min(m.assignment_id::text) into updates,assignments
    from jsonb_array_elements(p_rows)e join private.historical_question_migrations m on m.id=(e->>'id')::uuid;
  if updates<>1 or (select count(*) from jsonb_array_elements(p_rows)e join private.historical_question_migrations m on m.id=(e->>'id')::uuid)<>row_count
    then raise exception 'historical_question_candidates_mismatch' using errcode='23514'; end if;
  assignment_id:=assignments::uuid; updates:=0;
  perform private.lock_historical_question_assignment_v1(assignment_id,p_action='compact');
  for entry in select e from jsonb_array_elements(p_rows)e order by e->>'id' loop
    select * into strict candidate from private.historical_question_migrations where id=(entry->>'id')::uuid for update;
    before_doc:=entry->'before';
    if private.reviewed_exam_sha256_v1(before_doc)<>candidate.original_sha256
      or before_doc->>'kind' is distinct from candidate.kind or before_doc->>'contentVersionId' is not null
      or private.reviewed_exam_sha256_v1(before_doc->'body')<>candidate.body_sha256
      then raise exception 'historical_question_archive_mismatch' using errcode='23514'; end if;
    original:=private.historical_question_row_v1(candidate.kind,candidate.row_id,true);
    this_assignment:=private.historical_question_assignment_v1(candidate.kind,original);
    current_doc:=private.historical_question_document_v1(candidate.kind,original);
    if this_assignment<>assignment_id or private.reviewed_exam_sha256_v1(current_doc->'identity')<>candidate.identity_sha256
      or private.historical_question_meaning_v1(candidate.kind,original) is distinct from candidate.meaning
      then raise exception 'historical_question_current_changed' using errcode='40001'; end if;
    referenced:=original->>'content_version_id' is not null;
    if referenced and (original->>'content_version_id')::uuid<>candidate.content_version_id
      then raise exception 'historical_question_reference_changed' using errcode='40001'; end if;
    if not referenced and (p_action='restore' or candidate.state<>'prepared'
      or private.reviewed_exam_sha256_v1(current_doc)<>candidate.original_sha256)
      then raise exception 'historical_question_current_changed' using errcode='40001'; end if;
    -- Recheck at application time: another prepared historical batch can have
    -- attached a quiz reference since this candidate was prepared.
    if candidate.kind='assignment' and exists(select 1 from public.quiz_questions q
      where q.assignment_question_id=candidate.row_id and q.content_version_id is not null and q.content_version_id<>candidate.content_version_id)
      then raise exception 'historical_question_dependent_reference_mismatch' using errcode='23514'; end if;
    spec:=private.historical_question_spec_v1(candidate.kind);
    select array_agg(value) into fields from jsonb_array_elements_text(spec->'body');
    if p_action='compact' then
      select jsonb_object_agg(key,'null'::jsonb) into body_doc from unnest(fields)key;
      state_value:='compacted';
    else body_doc:=before_doc->'body'; state_value:='restored'; end if;
    patch:=body_doc||jsonb_build_object('content_version_id',candidate.content_version_id);
    changed:=original||patch;
    after_doc:=private.historical_question_document_v1(candidate.kind,private.historical_question_resolve_v1(candidate.kind,changed));
    if after_doc-'contentVersionId' is distinct from before_doc-'contentVersionId'
      then raise exception 'historical_question_read_mismatch' using errcode='23514'; end if;
    if referenced and current_doc->'body' is distinct from before_doc->'body' and
      exists(select 1 from jsonb_each(current_doc->'body')e where e.value<>'null'::jsonb)
      then raise exception 'historical_question_current_changed' using errcode='40001'; end if;
    if original is distinct from changed then
      insert into private.historical_question_write_permits values(pg_backend_pid(),txid_current(),(spec->>'relation')::regclass::oid,
        private.reviewed_exam_sha256_v1(original),private.reviewed_exam_sha256_v1(changed));
      select string_agg(format('%I=x.%I',field,field),',') into assignments from unnest(fields||array['content_version_id'])field;
      execute format('update %s q set %s from jsonb_populate_record(null::%s,$1) x where q.%I=$2',
        (spec->>'relation')::regclass,assignments,(spec->>'relation')::regclass,spec->>'key') using changed,candidate.row_id;
      if exists(select 1 from private.historical_question_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current())
        then raise exception 'historical_question_permit_unused' using errcode='55000'; end if;
      updates:=updates+1;
    end if;
    actual:=private.historical_question_row_v1(candidate.kind,candidate.row_id);
    if actual is distinct from changed or private.historical_question_meaning_v1(candidate.kind,actual) is distinct from candidate.meaning
      then raise exception 'historical_question_postcondition_failed' using errcode='23514'; end if;
    if candidate.kind in('assignment','exam-use') then
      perform private.keep_historical_question_meaning_v1(candidate.row_id,candidate.meaning);
    end if;
    update private.historical_question_migrations set state=state_value where id=candidate.id;
    details:=details||jsonb_build_array(jsonb_build_object('id',candidate.id,'kind',candidate.kind,'rowId',candidate.row_id,
      'originalHash',candidate.original_sha256,'currentHash',private.reviewed_exam_sha256_v1(private.historical_question_document_v1(candidate.kind,actual)),
      'contentVersionId',candidate.content_version_id,'state',state_value));
  end loop;
  result:=jsonb_build_object('requestId',p_request_id,'action',p_action,'rows',row_count,'changed',updates,'items',details);
  insert into private.historical_question_migration_receipts(request_id,request_sha256,archive_sha256,result)
    values(p_request_id,request_hash,p_archive_sha256,result);
  return result;
end $$;

do $permissions$
declare f record;
begin
  for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in(
      'historical_question_spec_v1','historical_question_document_v1','historical_question_row_v1','historical_question_assignment_v1',
      'historical_question_participants_v1','lock_historical_question_assignment_v1','historical_question_meaning_v1',
      'historical_question_resolve_v1','prepare_historical_question_batch_v1','consume_historical_question_permit_v1','apply_historical_question_batch_v1',
      'keep_historical_question_meaning_v1')
  loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature); end loop;
end;
$permissions$;

select set_config('search_path','public',true);
-- APP-20261003-03. Explicit operator batches only; no automatic backfill.
create table private.historical_learning_migrations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check(kind in ('scope','composition')),
  group_id uuid not null,
  occurrence_key text not null check(occurrence_key ~ '^[a-f0-9]{64}$'),
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  compacted_sha256 text not null check(compacted_sha256 ~ '^[a-f0-9]{64}$'),
  original_document_sha256 text check(original_document_sha256 ~ '^[a-f0-9]{64}$'),
  resource_refs jsonb not null,
  state text not null default 'prepared' check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp(),
  unique(kind,group_id,occurrence_key)
);
create table private.historical_learning_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  result jsonb not null,
  created_at timestamptz not null default clock_timestamp()
);
create table private.historical_learning_write_permits (
  backend_pid integer not null,
  transaction_id bigint not null,
  relation_id oid not null,
  before_sha256 text not null,
  after_sha256 text not null,
  primary key(backend_pid,transaction_id,relation_id,before_sha256)
);
alter table private.historical_learning_migrations enable row level security;
alter table private.historical_learning_receipts enable row level security;
alter table private.historical_learning_write_permits enable row level security;
revoke all on private.historical_learning_migrations,private.historical_learning_receipts,
  private.historical_learning_write_permits from public,anon,authenticated,service_role;
create trigger historical_learning_receipt_immutable before update or delete on private.historical_learning_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

-- Unlike the new-import projector, this pure projector never reads today's
-- dictionary bridge or meaning approvals. Missing historical facts stay absent.
create function private.project_historical_learning_binding_v1(p_entry jsonb,p_occurrence jsonb,p_resources jsonb,p_source jsonb,p_selection_sha256 text)
returns jsonb language plpgsql immutable set search_path='' as $$
declare selected jsonb:=p_resources->'selected'; entry_link jsonb:='null'; result jsonb; ids jsonb; learning jsonb;
  has_entry boolean:=p_entry is not null and p_entry<>'null'::jsonb;
  has_occurrence boolean:=p_occurrence is not null and p_occurrence<>'null'::jsonb;
begin
  perform private.project_vocabulary_learning_value_v1(p_entry,selected);
  if has_entry then
    if not(p_entry ?& array['id','dataset_id','unit_id','source_row','row_sha256','source_ref']) then
      raise exception 'vocabulary_entry_link_missing' using errcode='22023'; end if;
    entry_link:=jsonb_build_object('id',p_entry->>'id','datasetId',p_entry->'dataset_id','unitId',p_entry->'unit_id',
      'sourceRow',p_entry->'source_row','rowHash',p_entry->'row_sha256','sourceRef',p_entry->'source_ref');
  end if;
  ids:=case when p_source->>'kind'='reviewed_exam' then p_occurrence->'payload' when p_source->>'kind'='exam_use' then p_occurrence else null end;
  learning:=jsonb_build_object('kind','source-occurrence-v1',
    'key',private.reviewed_exam_sha256_v1(jsonb_build_array('source-occurrence-v1',p_source->'occurrenceKey',p_source->'version','primary_meaning',
      private.reviewed_exam_sha256_v1(jsonb_build_array(p_entry->'primary_meaning',selected->'lexicalPos')))),
    'senseId',null,'lexicalPos',selected->'lexicalPos','reviewEvidenceHash',null);
  result:=jsonb_build_object('schemaVersion','vocabulary-source-binding-v1','selectionHash',p_selection_sha256,'source',p_source,'entryLink',entry_link,
    'originalHashes',jsonb_build_object('entrySnapshotHash',case when has_entry then private.reviewed_exam_sha256_v1(p_entry) end,
      'occurrenceSnapshotHash',case when has_occurrence then private.reviewed_exam_sha256_v1(p_occurrence) end,
      'selectedSnapshotHash',private.reviewed_exam_sha256_v1(selected),
      'dictionarySnapshotHash',case when selected->'dictionary'<>'null'::jsonb then private.reviewed_exam_sha256_v1(selected->'dictionary') end),
    'selectedDictionary',private.project_vocabulary_dictionary_link_v1(selected->'dictionary'),'selectedSenseId',selected->'senseId',
    'sourceIdentifiers',jsonb_build_object('dictionaryId',ids->'dictionary_id','legacyIds',coalesce(nullif(ids->'legacy_ids','null'::jsonb),'[]'::jsonb),
      'occurrenceId',ids->'occurrence_id','senseId',ids->'sense_id','sourceEntryId',ids->'source_entry_id','sourceEntryHash',ids->'source_entry_sha256',
      'legacyLexemeId',null,'legacyOccurrenceId',null,'legacyMappingStatus',null),
    'proofs',private.project_vocabulary_proofs_v1(selected->'proofs'),'learningIdentity',learning);
  perform private.validate_vocabulary_learning_binding_v1(result);
  return result;
end $$;

do $copy$
declare d text;
begin
  d:=pg_get_functiondef('private.register_vocabulary_learning_resources_v1(jsonb,jsonb,jsonb,jsonb)'::regprocedure);
  if length(d)-length(replace(d,'private.project_vocabulary_learning_binding_v1(',''))<>length('private.project_vocabulary_learning_binding_v1(') then
    raise exception 'historical_learning_registration_anchor_changed'; end if;
  d:=replace(d,'private.register_vocabulary_learning_resources_v1(','private.register_historical_learning_resources_v1(');
  execute replace(d,'private.project_vocabulary_learning_binding_v1(','private.project_historical_learning_binding_v1(');
end $copy$;

create function private.historical_learning_row_v1(p_kind text,p_group uuid,p_key text) returns jsonb
language plpgsql stable set search_path='' as $$
declare result jsonb;
begin
  if p_kind='scope' then select to_jsonb(r) into result from private.vocabulary_library_scope_rows r where scope_id=p_group and occurrence_key=p_key;
  elsif p_kind='composition' then select to_jsonb(r) into result from private.vocabulary_composition_entries r where version_id=p_group and occurrence_key=p_key;
  else raise exception 'historical_learning_kind_invalid' using errcode='22023'; end if;
  if result is null then raise exception 'historical_learning_row_missing' using errcode='P0002'; end if;
  return result;
end $$;

create function private.assert_historical_learning_row_v1(p_kind text,p_group uuid,p_key text) returns void
language plpgsql stable set search_path='' as $$
declare m private.historical_learning_migrations; r jsonb; resources jsonb; binding jsonb;
begin
  select * into m from private.historical_learning_migrations where kind=p_kind and group_id=p_group and occurrence_key=p_key;
  if not found then return; end if;
  r:=private.historical_learning_row_v1(p_kind,p_group,p_key);
  if private.reviewed_exam_sha256_v1(r) is distinct from (case when m.state='compacted' then m.compacted_sha256 else m.original_sha256 end) then
    raise exception 'historical_learning_row_changed' using errcode='40001'; end if;
  if m.state='compacted' then
    resources:=r->'resources'; binding:=private.resolve_vocabulary_learning_binding_v1(resources);
    if jsonb_build_object('selected',resources->'selected','selectionBinding',resources->'selectionBinding') is distinct from m.resource_refs
      or coalesce(r#>>'{entry_snapshot,recordHash}',r#>>'{source_snapshot,entry,recordHash}') is distinct from binding#>>'{originalHashes,entrySnapshotHash}'
      or coalesce(r#>>'{occurrence_snapshot,recordHash}',r#>>'{source_snapshot,occurrence,recordHash}') is distinct from binding#>>'{originalHashes,occurrenceSnapshotHash}' then
      raise exception 'historical_learning_reference_changed' using errcode='40001'; end if;
  end if;
end $$;

-- Keep the logical fingerprint and fixed version unchanged; verify the physical
-- representation through the small migration receipt before expanding it.
do $copy$
begin
  execute replace(pg_get_functiondef('private.vocabulary_library_row_document_v1(uuid,text)'::regprocedure),
    'private.vocabulary_library_row_document_v1(','private.historical_learning_raw_scope_document_v1(');
  execute replace(pg_get_functiondef('private.vocabulary_composition_preparation_v1(uuid)'::regprocedure),
    'private.vocabulary_composition_preparation_v1(','private.historical_learning_preparation_before_v1(');
end $copy$;
create or replace function private.vocabulary_library_row_document_v1(p_scope_id uuid,p_key text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
  perform private.assert_historical_learning_row_v1('scope',p_scope_id,p_key);
  return private.historical_learning_raw_scope_document_v1(p_scope_id,p_key);
end $$;
create or replace function private.vocabulary_composition_preparation_v1(p_version_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare m record;
begin
  for m in select occurrence_key from private.historical_learning_migrations where kind='composition' and group_id=p_version_id loop
    perform private.assert_historical_learning_row_v1('composition',p_version_id,m.occurrence_key);
  end loop;
  return private.historical_learning_preparation_before_v1(p_version_id);
end $$;

create function private.assert_historical_learning_scopes_v1(p_recipe jsonb) returns void
language plpgsql stable set search_path='' as $$
declare m record;
begin
  for m in select h.group_id,h.occurrence_key from private.historical_learning_migrations h
    where h.kind='scope' and h.group_id in(select (x->>'id')::uuid from jsonb_array_elements(p_recipe->'scopes') x) loop
    perform private.assert_historical_learning_row_v1('scope',m.group_id,m.occurrence_key);
    if not exists(select 1 from private.vocabulary_library_row_fingerprints f join private.historical_learning_migrations h
      on h.kind='scope' and h.group_id=f.scope_id and h.occurrence_key=f.occurrence_key
      where f.scope_id=m.group_id and f.occurrence_key=m.occurrence_key and f.document_sha256=h.original_document_sha256) then
      raise exception 'historical_learning_fingerprint_changed' using errcode='40001'; end if;
  end loop;
end $$;

do $patch$
declare d text; anchor text; signature text;
begin
  foreach signature in array array['private.resolve_vocabulary_library_recipe_compact_v1(jsonb)','private.assert_vocabulary_library_version_current_v1(private.vocabulary_library_versions)'] loop
    d:=replace(pg_get_functiondef(signature::regprocedure),chr(13),'');
    anchor:=E'begin\n';
    if strpos(d,anchor)=0 then raise exception 'historical_learning_reader_anchor_changed'; end if;
    execute overlay(d placing anchor||'  perform private.assert_historical_learning_scopes_v1('||
      case when signature like '%recipe_compact%' then 'r' else 'v.recipe' end||E');\n' from strpos(d,anchor) for length(anchor));
  end loop;
  d:=pg_get_functiondef('private.assignment_vocabulary_meaning_v1(uuid,integer)'::regprocedure);
  anchor:='    source_entry:=c.source_entry_id; source_kind:=c.source_kind; source_release:=c.source_release_id;';
  if length(d)-length(replace(d,anchor,''))<>length(anchor) then raise exception 'historical_learning_meaning_anchor_changed'; end if;
  execute replace(d,anchor,$new$
    perform private.assert_historical_learning_row_v1('composition',c.version_id,c.occurrence_key);
    -- Preserve the historical M03 branch, including its selected dictionary
    -- precedence. Do not adopt the later v2/current-review identity recipe.
    if exists(select 1 from private.historical_learning_migrations where kind='composition' and group_id=c.version_id
        and occurrence_key=c.occurrence_key and state='compacted') then
      c.resources:=jsonb_set(c.resources,'{selected}',private.vocabulary_composition_resource_v1(c.resources));
    end if;
    source_entry:=c.source_entry_id; source_kind:=c.source_kind; source_release:=c.source_release_id;$new$);
end $patch$;

-- A later, newly requested composition must retain its existing creation
-- policy. A raw old scope used to consult current reviewed identity/bridge at
-- that point. Recreate ONLY that new binding; never promote the migrated scope
-- or an already completed composition to today's identity.
create function private.historical_learning_resources_for_new_composition_v1(p_scope_id uuid,p_key text,p_resources jsonb,p_source jsonb)
returns jsonb language plpgsql volatile set search_path='' as $$
declare b jsonb; value_doc jsonb; entry_doc jsonb; selected_doc jsonb; bridge word_index.vocab_entry_link;
  bh text; stored private.vocabulary_learning_value_bindings;
begin
  perform private.assert_historical_learning_row_v1('scope',p_scope_id,p_key);
  b:=private.resolve_vocabulary_learning_binding_v1(p_resources);
  if b->'source' is distinct from p_source then raise exception 'vocabulary_source_content_mismatch' using errcode='40001'; end if;
  value_doc:=private.resolve_vocabulary_learning_value_v1(p_resources->'selected');
  selected_doc:=private.vocabulary_composition_resource_v1(p_resources);
  entry_doc:=case when b->'entryLink'='null'::jsonb then null else (value_doc->'entryValues')||jsonb_build_object(
    'id',b#>'{entryLink,id}','dataset_id',b#>'{entryLink,datasetId}','unit_id',b#>'{entryLink,unitId}',
    'source_row',b#>'{entryLink,sourceRow}','row_sha256',b#>'{entryLink,rowHash}','source_ref',b#>'{entryLink,sourceRef}') end;
  if entry_doc is not null then
    select * into bridge from word_index.vocab_entry_link where vocab_entry_id=(entry_doc->>'id')::bigint;
    if found and (bridge.dataset_id::text is distinct from entry_doc->>'dataset_id' or bridge.entry_row_sha256 is distinct from entry_doc->>'row_sha256') then
      raise exception 'vocabulary_legacy_link_mismatch' using errcode='40001'; end if;
  end if;
  b:=jsonb_set(b,'{sourceIdentifiers}',(b->'sourceIdentifiers')||jsonb_build_object('legacyLexemeId',bridge.lexeme_id,
    'legacyOccurrenceId',bridge.occurrence_id,'legacyMappingStatus',bridge.mapping_status));
  b:=jsonb_set(b,'{learningIdentity}',private.vocabulary_learning_identity_v1(entry_doc,p_source,selected_doc));
  perform private.validate_vocabulary_learning_binding_v1(b);
  bh:=private.reviewed_exam_sha256_v1(b);
  insert into private.vocabulary_learning_value_bindings(binding_sha256,selection_id,selection_sha256,payload)
    values(bh,(p_resources#>>'{selected,selectionId}')::uuid,p_resources#>>'{selected,selectionHash}',b) on conflict(binding_sha256) do nothing;
  select * into stored from private.vocabulary_learning_value_bindings where binding_sha256=bh;
  if not found or stored.payload is distinct from b or stored.selection_id is distinct from (p_resources#>>'{selected,selectionId}')::uuid then
    raise exception 'vocabulary_binding_conflict' using errcode='40001'; end if;
  return jsonb_set(p_resources,'{selectionBinding}',jsonb_build_object('schemaVersion','vocabulary-source-binding-ref-v1','bindingId',stored.binding_id,'bindingHash',bh));
end $$;
do $patch$
declare d text; anchor text;
begin
  d:=pg_get_functiondef('private.vocabulary_composition_row_document_v2(uuid,text,uuid[])'::regprocedure);
  anchor:='  saved_resources:=private.register_vocabulary_learning_resources_v1(r.entry_snapshot,r.occurrence_snapshot,r.resources,source_doc);';
  if length(d)-length(replace(d,anchor,''))<>length(anchor) then raise exception 'historical_learning_new_composition_anchor_changed'; end if;
  execute replace(d,anchor,$new$
  if exists(select 1 from private.historical_learning_migrations where kind='scope' and group_id=p_scope_id and occurrence_key=p_key and state='compacted') then
    saved_resources:=private.historical_learning_resources_for_new_composition_v1(p_scope_id,p_key,r.resources,source_doc);
  else
    saved_resources:=private.register_vocabulary_learning_resources_v1(r.entry_snapshot,r.occurrence_snapshot,r.resources,source_doc);
  end if;$new$);
end $patch$;

create function private.lock_historical_learning_batch_v1(p_kind text,p_group uuid,p_keys text[],p_compact boolean) returns void
language plpgsql set search_path='' as $$
declare versions uuid[]; datasets uuid[]; assignment_ids uuid[]; c private.vocabulary_compositions;
  expected integer; qplan private.vocabulary_composition_question_plans;
begin
  if current_user<>'postgres' then raise exception 'historical_learning_operator_required' using errcode='42501'; end if;
  if current_setting('transaction_isolation')<>'read committed'
    or (select setting::integer from pg_settings where name='statement_timeout') not between 1 and 30000
    or (select setting::integer from pg_settings where name='lock_timeout') not between 1 and 1000 then
    raise exception 'historical_learning_transaction_limits_required' using errcode='22023'; end if;
  if p_kind is null or p_kind not in('scope','composition') or p_group is null or cardinality(p_keys) not between 1 and 100
    or p_keys is null or exists(select 1 from unnest(p_keys) k where k is null or k !~ '^[a-f0-9]{64}$')
    or cardinality(p_keys)<>(select count(distinct k) from unnest(p_keys) k) then
    raise exception 'historical_learning_batch_invalid' using errcode='22023'; end if;
  -- Fail immediately when normal work holds any conflicting lock. No student
  -- locks or waits in the opposite order of app creation/start paths.
  lock table private.vocabulary_library_versions in share row exclusive mode nowait;
  lock table private.vocabulary_compositions in share row exclusive mode nowait;
  lock table private.vocabulary_composition_entries in share row exclusive mode nowait;
  lock table private.vocabulary_library_scope_rows in share row exclusive mode nowait;
  if p_kind='scope' then
    select coalesce(array_agg(distinct id),'{}') into versions from (
      select v.id from private.vocabulary_library_versions v where exists(select 1 from jsonb_array_elements(v.recipe->'scopes') x where (x->>'id')::uuid=p_group)
      union select version_id from private.vocabulary_composition_build_positions where p_group=any(scope_ids)
      union select version_id from private.vocabulary_composition_entries where p_group=any(source_scope_ids)
    ) related;
    select array[dataset_id] into datasets from private.vocabulary_library_scopes where id=p_group;
  else
    versions:=array[p_group];
    select coalesce(array_agg(distinct s.dataset_id),'{}') into datasets from private.vocabulary_composition_entries e
      join private.vocabulary_library_scopes s on s.id=any(e.source_scope_ids) where e.version_id=p_group;
  end if;
  select coalesce(array_agg(distinct id),'{}') into datasets from (
    select unnest(datasets) id union select dataset_id from private.vocabulary_compositions where version_id=any(versions)
  ) d;
  perform 1 from public.vocab_datasets where id=any(datasets) order by id for update nowait;
  perform 1 from public.vocab_dataset_catalog where dataset_id=any(datasets) order by dataset_id for update nowait;
  perform 1 from private.vocabulary_compositions where version_id=any(versions) order by version_id for update nowait;
  -- Include original-dataset/direct assignments and stored composition links.
  select coalesce(array_agg(id order by id),'{}') into assignment_ids from public.assignments a where a.dataset_id=any(datasets)
    or exists(select 1 from public.assignment_sources x where x.assignment_id=a.id and x.dataset_id=any(datasets))
    or exists(select 1 from public.assignment_questions q where q.assignment_id=a.id and
      (q.dataset_id=any(datasets) or q.composition_version_id_snapshot=any(versions) or q.vocab_entry_id in
        (select source_entry_id from private.vocabulary_library_scope_rows where p_kind='scope' and scope_id=p_group and occurrence_key=any(p_keys))));
  perform 1 from public.assignments where id=any(assignment_ids) order by id for update nowait;
  if p_kind='scope' then perform 1 from private.vocabulary_library_scope_rows where scope_id=p_group and occurrence_key=any(p_keys) order by occurrence_key for update nowait;
  else perform 1 from private.vocabulary_composition_entries where version_id=p_group and occurrence_key=any(p_keys) order by occurrence_key for update nowait; end if;
  -- Fresh READ COMMITTED statements after all relevant parents are locked.
  for c in select * from private.vocabulary_compositions where version_id=any(versions) loop
    if c.state<>'ready' or c.question_sha256 is null then raise exception 'historical_learning_build_pending' using errcode='55000'; end if;
    if exists(select 1 from private.vocabulary_composition_builds where version_id=c.version_id and
        (not preparation_complete or next_row<>total_count+1)) then raise exception 'historical_learning_build_pending' using errcode='55000'; end if;
    perform private.assert_vocabulary_composition_build_complete_v1(c.version_id);
    select jsonb_array_length(fixed_composition->'includedKeys') into expected from private.vocabulary_library_versions where id=c.version_id;
    if expected is null or expected<>(select count(*) from private.vocabulary_composition_entries where version_id=c.version_id)
      or expected<>(select count(*) from public.vocab_entries where dataset_id=c.dataset_id)
      or c.question_sha256 is distinct from (select private.reviewed_exam_sha256_v1(coalesce(jsonb_agg(item_sha256 order by item_id),'[]'))
        from private.vocabulary_composition_items where version_id=c.version_id) then
      raise exception 'historical_learning_build_incomplete' using errcode='40001'; end if;
    select * into qplan from private.vocabulary_composition_question_plans where version_id=c.version_id;
    if found and (qplan.processed_count<>qplan.total_count or qplan.total_count<>(select count(*) from private.vocabulary_composition_items
      where version_id=c.version_id and source_kind='generated_meaning')) then raise exception 'historical_learning_plan_pending' using errcode='55000'; end if;
  end loop;
  if p_kind='composition' and not exists(select 1 from private.vocabulary_compositions where version_id=p_group) then
    raise exception 'historical_learning_row_missing' using errcode='P0002'; end if;
  if not p_compact then return; end if;
  if exists(select 1 from public.assignments where id=any(assignment_ids) and not coalesce(status='closed' or deleted_at is not null
      or (isfinite(available_until) and available_until<clock_timestamp()),false))
    or exists(select 1 from public.quiz_attempts where assignment_id=any(assignment_ids) and (status='in_progress' or completed_at is null or phase in('review','retry')))
    or exists(select 1 from private.quiz_attempt_preparations where assignment_id=any(assignment_ids) and begun_id is null)
    or exists(select 1 from private.local_quiz_runs r join public.quiz_attempts a on a.id=r.attempt_id where a.assignment_id=any(assignment_ids))
    or exists(select 1 from private.local_quiz_preparations l join private.quiz_attempt_preparations p on p.id=l.preparation_id where p.assignment_id=any(assignment_ids)) then
    raise exception 'historical_learning_student_work_pending' using errcode='55000'; end if;
end $$;

create function private.historical_learning_compacted_row_v1(p_kind text,p_before jsonb,p_refs jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare result jsonb:=p_before; d jsonb; resources jsonb:=(p_before->'resources')||p_refs;
begin
  if p_kind='scope' then
    return result||jsonb_build_object('entry_snapshot',private.compact_vocabulary_source_snapshot_v1(p_before->'entry_snapshot','entry'),
      'occurrence_snapshot',private.compact_vocabulary_source_snapshot_v1(p_before->'occurrence_snapshot','occurrence'),'resources',resources);
  elsif p_kind='composition' then
    d:=p_before->'source_snapshot';
    if d->'resources' is distinct from p_before->'resources' then raise exception 'historical_learning_resources_mismatch' using errcode='40001'; end if;
    d:=d||jsonb_build_object('entry',private.compact_vocabulary_source_snapshot_v1(d->'entry','entry'),
      'occurrence',private.compact_vocabulary_source_snapshot_v1(d->'occurrence','occurrence'),'resources',resources);
    return result||jsonb_build_object('source_snapshot',d,'resources',resources);
  end if;
  raise exception 'historical_learning_kind_invalid' using errcode='22023';
end $$;

create function private.prepare_historical_learning_batch_v1(p_kind text,p_group uuid,p_keys text[]) returns jsonb
language plpgsql set search_path='' as $$
declare k text; r jsonb; e jsonb; o jsonb; resources jsonb; refs jsonb; source_doc jsonb; after_doc jsonb; source_scope uuid;
  s private.vocabulary_library_scopes; m private.historical_learning_migrations; h text; doc_h text; result jsonb:='[]';
begin
  perform private.lock_historical_learning_batch_v1(p_kind,p_group,p_keys,true);
  for k in select x from unnest(p_keys) x order by x loop
    r:=private.historical_learning_row_v1(p_kind,p_group,k);
    if r#>>'{resources,selected,schemaVersion}' is distinct from 'vocabulary-resource-snapshot-v1' then
      raise exception 'historical_learning_inline_required' using errcode='22023'; end if;
    if p_kind='scope' then source_scope:=p_group; e:=r->'entry_snapshot'; o:=r->'occurrence_snapshot';
    else source_scope:=(r#>>'{source_scope_ids,0}')::uuid; e:=r#>'{source_snapshot,entry}'; o:=r#>'{source_snapshot,occurrence}'; end if;
    select * into s from private.vocabulary_library_scopes where id=source_scope;
    if not found then raise exception 'historical_learning_source_missing' using errcode='40001'; end if;
    source_doc:=jsonb_build_object('kind',s.source_kind,'datasetId',s.dataset_id,'unitId',s.unit_id,'releaseId',s.source_release_id,
      'version',s.source_version,'fileHash',s.source_file_sha256,'locator',s.payload#>'{source,locator}',
      'sourceRow',case when p_kind='scope' then r->'source_row' else r#>'{source_snapshot,sourceRow}' end,
      'occurrenceKey',k,'state',case when p_kind='scope' then r->'state' else r#>'{source_snapshot,state}' end);
    resources:=private.register_historical_learning_resources_v1(e,o,r->'resources',source_doc);
    refs:=jsonb_build_object('selected',resources->'selected','selectionBinding',resources->'selectionBinding');
    -- Fresh statement after registration, before an immutable row is touched.
    perform private.resolve_vocabulary_learning_binding_v1(resources);
    after_doc:=private.historical_learning_compacted_row_v1(p_kind,r,refs); h:=private.reviewed_exam_sha256_v1(r); doc_h:=null;
    if p_kind='scope' then
      doc_h:=private.reviewed_exam_sha256_v1(private.historical_learning_raw_scope_document_v1(p_group,k));
      insert into private.vocabulary_library_row_fingerprints(scope_id,occurrence_key,document_sha256) values(p_group,k,doc_h) on conflict do nothing;
      if not exists(select 1 from private.vocabulary_library_row_fingerprints where scope_id=p_group and occurrence_key=k and document_sha256=doc_h) then
        raise exception 'historical_learning_fingerprint_changed' using errcode='40001'; end if;
    end if;
    insert into private.historical_learning_migrations(kind,group_id,occurrence_key,original_sha256,compacted_sha256,original_document_sha256,resource_refs)
      values(p_kind,p_group,k,h,private.reviewed_exam_sha256_v1(after_doc),doc_h,refs) on conflict(kind,group_id,occurrence_key) do nothing;
    select * into m from private.historical_learning_migrations where kind=p_kind and group_id=p_group and occurrence_key=k;
    if m.original_sha256 is distinct from h or m.compacted_sha256 is distinct from private.reviewed_exam_sha256_v1(after_doc)
      or m.resource_refs is distinct from refs then raise exception 'historical_learning_preparation_changed' using errcode='40001'; end if;
    result:=result||jsonb_build_array(jsonb_build_object('id',m.id,'beforeText',r::text));
  end loop;
  if octet_length(result::text)>4194304 then raise exception 'historical_learning_batch_too_large' using errcode='22023'; end if;
  return result;
end $$;

create function private.guard_historical_learning_write_v1() returns trigger
language plpgsql set search_path='' as $$
begin
  if tg_op='UPDATE' then
    delete from private.historical_learning_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()
      and relation_id=tg_relid and before_sha256=private.reviewed_exam_sha256_v1(to_jsonb(old))
      and after_sha256=private.reviewed_exam_sha256_v1(to_jsonb(new));
    if found then return new; end if;
  end if;
  raise exception 'mock_wordbook_history_is_immutable' using errcode='22023';
end $$;
drop trigger vocabulary_library_rows_immutable on private.vocabulary_library_scope_rows;
create trigger vocabulary_library_rows_immutable before update or delete on private.vocabulary_library_scope_rows
  for each row execute function private.guard_historical_learning_write_v1();
drop trigger vocabulary_composition_entries_immutable on private.vocabulary_composition_entries;
create trigger vocabulary_composition_entries_immutable before update or delete on private.vocabulary_composition_entries
  for each row execute function private.guard_historical_learning_write_v1();

create function private.apply_historical_learning_batch_v1(p_request_id uuid,p_action text,p_archive_sha256 text,p_rows jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare request_hash text; receipt private.historical_learning_receipts; m private.historical_learning_migrations;
  first_row private.historical_learning_migrations; packet jsonb; before_doc jsonb; current_doc jsonb; next_doc jsonb;
  keys text[]; meanings_before jsonb; meanings_after jsonb; result jsonb; changed integer:=0; key_column text;
  relation_name text; relation_id oid;
begin
  if current_user<>'postgres' then raise exception 'historical_learning_operator_required' using errcode='42501'; end if;
  if p_request_id is null or p_action is null or p_action not in('compact','restore') or p_archive_sha256 is null or p_archive_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 100 or octet_length(p_rows::text)>4194304 then
    raise exception 'historical_learning_batch_invalid' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(p_rows) x where jsonb_typeof(x) is distinct from 'object'
    or not(x ?& array['id','beforeText']) or x-array['id','beforeText']<>'{}'::jsonb or jsonb_typeof(x->'beforeText') is distinct from 'string')
    or (select count(distinct (x->>'id')::uuid) from jsonb_array_elements(p_rows) x)<>jsonb_array_length(p_rows) then
    raise exception 'historical_learning_batch_invalid' using errcode='22023'; end if;
  request_hash:=private.reviewed_exam_sha256_v1(jsonb_build_array(p_action,p_archive_sha256,p_rows));
  select * into receipt from private.historical_learning_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'historical_learning_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  select * into first_row from private.historical_learning_migrations where id=(p_rows#>>'{0,id}')::uuid;
  if not found then raise exception 'historical_learning_preparation_missing' using errcode='P0002'; end if;
  select array_agg(h.occurrence_key order by h.occurrence_key) into keys from private.historical_learning_migrations h
    where h.id in(select (x->>'id')::uuid from jsonb_array_elements(p_rows) x) and h.kind=first_row.kind and h.group_id=first_row.group_id;
  if cardinality(keys) is distinct from jsonb_array_length(p_rows) then raise exception 'historical_learning_batch_mixed' using errcode='22023'; end if;
  perform private.lock_historical_learning_batch_v1(first_row.kind,first_row.group_id,keys,p_action='compact');
  select * into receipt from private.historical_learning_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'historical_learning_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  for packet in select x from jsonb_array_elements(p_rows) x order by (x->>'id')::uuid loop
    select * into m from private.historical_learning_migrations where id=(packet->>'id')::uuid for update nowait;
    before_doc:=(packet->>'beforeText')::jsonb;
    if private.reviewed_exam_sha256_v1(before_doc) is distinct from m.original_sha256 then
      raise exception 'historical_learning_archive_changed' using errcode='40001'; end if;
    current_doc:=private.historical_learning_row_v1(m.kind,m.group_id,m.occurrence_key);
    perform private.assert_historical_learning_row_v1(m.kind,m.group_id,m.occurrence_key);
    next_doc:=private.historical_learning_compacted_row_v1(m.kind,before_doc,m.resource_refs);
    if private.reviewed_exam_sha256_v1(next_doc) is distinct from m.compacted_sha256 then raise exception 'historical_learning_reference_changed' using errcode='40001'; end if;
    if p_action='restore' then next_doc:=before_doc; end if;
    if current_doc=next_doc then continue; end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'meaning',private.assignment_vocabulary_meaning_v1(q.id)) order by q.id),'[]') into meanings_before
      from public.assignment_questions q where q.vocab_entry_id=(current_doc->>'vocab_entry_id')::bigint and q.composition_version_id_snapshot=m.group_id;
    if m.kind='scope' then relation_name:='private.vocabulary_library_scope_rows'; key_column:='scope_id';
    else relation_name:='private.vocabulary_composition_entries'; key_column:='version_id'; end if;
    relation_id:=relation_name::regclass;
    insert into private.historical_learning_write_permits values(pg_backend_pid(),txid_current(),relation_id,
      private.reviewed_exam_sha256_v1(current_doc),private.reviewed_exam_sha256_v1(next_doc));
    if m.kind='scope' then
      update private.vocabulary_library_scope_rows set entry_snapshot=nullif(next_doc->'entry_snapshot','null'::jsonb),
        occurrence_snapshot=nullif(next_doc->'occurrence_snapshot','null'::jsonb),resources=next_doc->'resources' where scope_id=m.group_id and occurrence_key=m.occurrence_key;
    else
      update private.vocabulary_composition_entries set source_snapshot=next_doc->'source_snapshot',resources=next_doc->'resources'
        where version_id=m.group_id and occurrence_key=m.occurrence_key;
    end if;
    if exists(select 1 from private.historical_learning_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()) then
      raise exception 'historical_learning_permit_not_consumed' using errcode='55000'; end if;
    update private.historical_learning_migrations set state=case when p_action='compact' then 'compacted' else 'restored' end where id=m.id;
    perform private.assert_historical_learning_row_v1(m.kind,m.group_id,m.occurrence_key);
    select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'meaning',private.assignment_vocabulary_meaning_v1(q.id)) order by q.id),'[]') into meanings_after
      from public.assignment_questions q where q.vocab_entry_id=(current_doc->>'vocab_entry_id')::bigint and q.composition_version_id_snapshot=m.group_id;
    if meanings_before is distinct from meanings_after then raise exception 'historical_learning_meaning_changed' using errcode='40001'; end if;
    changed:=changed+1;
  end loop;
  result:=jsonb_build_object('requestId',p_request_id,'action',p_action,'rows',jsonb_array_length(p_rows),'changed',changed,'archiveHash',p_archive_sha256);
  insert into private.historical_learning_receipts(request_id,request_sha256,archive_sha256,result) values(p_request_id,request_hash,p_archive_sha256,result);
  return result;
end $$;

-- Private operators and support helpers have no app-role execution grant.
do $acl$
declare r record;
begin
  for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and (p.proname like '%historical_learning%' or p.proname in
      ('vocabulary_library_row_document_v1','vocabulary_composition_preparation_v1')) loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);
  end loop;
end $acl$;

select set_config('search_path','public',true);
-- APP-20261003-04. One explicitly archived bundle; never automatic cleanup.
create table private.reviewed_bundle_archives (
  release_id uuid primary key references private.reviewed_mock_source_releases_v1(release_id),
  target_project_ref text not null,
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  compacted_sha256 text not null check(compacted_sha256 ~ '^[a-f0-9]{64}$'),
  bundle_sha256 text not null check(bundle_sha256 ~ '^[a-f0-9]{64}$'),
  original_bytes integer not null check(original_bytes between 1 and 16777216),
  state text not null check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp()
);
create table private.reviewed_bundle_archive_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  release_id uuid not null references private.reviewed_bundle_archives(release_id),
  result jsonb not null,
  created_at timestamptz not null default clock_timestamp()
);
create table private.reviewed_bundle_write_permits (
  backend_pid integer not null,
  transaction_id bigint not null,
  release_id uuid not null,
  before_sha256 text not null,
  after_sha256 text not null,
  primary key(backend_pid,transaction_id,release_id)
);
alter table private.reviewed_bundle_archives enable row level security;
alter table private.reviewed_bundle_archive_receipts enable row level security;
alter table private.reviewed_bundle_write_permits enable row level security;
revoke all on private.reviewed_bundle_archives,private.reviewed_bundle_archive_receipts,private.reviewed_bundle_write_permits
  from public,anon,authenticated,service_role;
create trigger reviewed_bundle_receipt_immutable before update or delete on private.reviewed_bundle_archive_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

-- This is the PostgreSQL JSONB representation hash, NOT the approved import
-- file byte hash or its recursive canonical content hash. Callers serialize
-- the complete row under UTC/ISO before hashing or writing beforeText.
create function private.reviewed_bundle_row_sha256_v1(p_value jsonb) returns text
language sql immutable strict set search_path='' as $$
  select encode(extensions.digest(convert_to(p_value::text,'UTF8'),'sha256'),'hex');
$$;
create function private.reviewed_bundle_compacted_row_v1(p_row jsonb) returns jsonb
language sql immutable strict set search_path='' as $$
  select jsonb_set(p_row,'{bundle}',jsonb_build_object(
    'schemaVersion','reviewed-bundle-archive-v1','hashFormat','postgres-jsonb-text-sha256-v1',
    'releaseId',p_row->'release_id','contentHash',p_row->'content_sha256',
    'originalRowHash',private.reviewed_bundle_row_sha256_v1(p_row),
    'bundleHash',private.reviewed_bundle_row_sha256_v1(p_row->'bundle')));
$$;

create function private.check_reviewed_bundle_operator_v1() returns void
language plpgsql set search_path='' as $$
begin
  if current_user<>'postgres' then raise exception 'reviewed_bundle_operator_required' using errcode='42501'; end if;
  if current_setting('transaction_isolation')<>'read committed'
    or (select setting::integer from pg_settings where name='statement_timeout') not between 1 and 30000
    or (select setting::integer from pg_settings where name='lock_timeout') not between 1 and 1000 then
    raise exception 'reviewed_bundle_transaction_limits_required' using errcode='22023'; end if;
end $$;

create function private.lock_reviewed_bundle_v1(p_release_id uuid,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare dataset_key text; project_ref text; doc jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_release_id is null or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then
    raise exception 'reviewed_bundle_identity_invalid' using errcode='22023'; end if;
  select a.dataset_key,r.target_project_ref into dataset_key,project_ref
    from private.reviewed_mock_source_releases_v1 r join private.reviewed_mock_source_approvals_v1 a
      on a.approval_id=r.approval_id and a.target_project_ref=r.target_project_ref where r.release_id=p_release_id;
  if not found then raise exception 'reviewed_bundle_missing' using errcode='P0002'; end if;
  if project_ref<>p_target_project_ref then raise exception 'reviewed_bundle_project_mismatch' using errcode='22023'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended(dataset_key,9129)) then
    raise exception 'reviewed_bundle_busy' using errcode='55P03'; end if;
  select to_jsonb(r) into doc from private.reviewed_mock_source_releases_v1 r where r.release_id=p_release_id for update nowait;
  if doc is null then raise exception 'reviewed_bundle_missing' using errcode='P0002'; end if;
  return doc;
end $$;

create function private.list_reviewed_bundle_candidates_v1(p_target_project_ref text) returns jsonb
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare result jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then
    raise exception 'reviewed_bundle_identity_invalid' using errcode='22023'; end if;
  -- No maximum-ID cursor. A newly committed smaller key remains discoverable.
  select coalesce(jsonb_agg(jsonb_build_object('releaseId',r.release_id,'contentHash',r.content_sha256)
    order by r.release_id),'[]') into result from private.reviewed_mock_source_releases_v1 r
    left join private.reviewed_bundle_archives a on a.release_id=r.release_id
    where r.target_project_ref=p_target_project_ref and (a.release_id is null or a.state<>'compacted');
  return result;
end $$;

create function private.prepare_reviewed_bundle_archive_v1(p_release_id uuid,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare doc jsonb; next_doc jsonb; original_hash text; m private.reviewed_bundle_archives; body_text text; approved_hash text;
begin
  doc:=private.lock_reviewed_bundle_v1(p_release_id,p_target_project_ref);
  if doc#>>'{bundle,schemaVersion}'='reviewed-bundle-archive-v1' then
    raise exception 'reviewed_bundle_archive_file_required' using errcode='22023'; end if;
  if doc#>>'{bundle,schema_version}' is distinct from 'reviewed_mock_wordbook_v1' then
    raise exception 'reviewed_bundle_source_invalid' using errcode='22023'; end if;
  body_text:=doc::text;
  if octet_length(body_text)>16777216 then raise exception 'reviewed_bundle_row_too_large' using errcode='22023'; end if;
  select a.content_sha256 into approved_hash from private.reviewed_mock_source_approvals_v1 a
    where a.approval_id=doc->>'approval_id' and a.target_project_ref=p_target_project_ref;
  if doc#>>'{bundle,content_sha256}' is distinct from approved_hash or doc->>'content_sha256' is distinct from approved_hash
    or private.reviewed_exam_sha256_v1((doc->'bundle')-'content_sha256') is distinct from approved_hash then
    raise exception 'reviewed_bundle_content_changed' using errcode='40001'; end if;
  original_hash:=private.reviewed_bundle_row_sha256_v1(doc);
  next_doc:=private.reviewed_bundle_compacted_row_v1(doc);
  select * into m from private.reviewed_bundle_archives where release_id=p_release_id for update nowait;
  if found then
    if m.original_sha256<>original_hash or m.compacted_sha256<>private.reviewed_bundle_row_sha256_v1(next_doc)
      or m.target_project_ref<>p_target_project_ref or m.state='compacted' then
      raise exception 'reviewed_bundle_row_changed' using errcode='40001'; end if;
  else
    insert into private.reviewed_bundle_archives(release_id,target_project_ref,original_sha256,compacted_sha256,bundle_sha256,original_bytes,state)
      values(p_release_id,p_target_project_ref,original_hash,private.reviewed_bundle_row_sha256_v1(next_doc),
        private.reviewed_bundle_row_sha256_v1(doc->'bundle'),octet_length(body_text),'prepared');
  end if;
  return jsonb_build_object('id',p_release_id,'beforeText',body_text);
end $$;

create function private.guard_reviewed_bundle_write_v1() returns trigger
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
begin
  if tg_op='UPDATE' and to_jsonb(new)-'bundle'=to_jsonb(old)-'bundle' then
    delete from private.reviewed_bundle_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()
      and release_id=old.release_id and before_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(old))
      and after_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(new));
    if found then return new; end if;
  end if;
  raise exception 'reviewed_mock_source_immutable' using errcode='22023';
end $$;
drop trigger reviewed_mock_release_immutable on private.reviewed_mock_source_releases_v1;
create trigger reviewed_mock_release_immutable before update or delete on private.reviewed_mock_source_releases_v1
  for each row execute function private.guard_reviewed_bundle_write_v1();

create function private.apply_reviewed_bundle_archive_v1(p_request_id uuid,p_action text,p_target_project_ref text,p_archive_sha256 text,p_packet jsonb)
returns jsonb language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare request_hash text; receipt private.reviewed_bundle_archive_receipts; m private.reviewed_bundle_archives;
  before_doc jsonb; current_doc jsonb; next_doc jsonb; v_release_id uuid; current_hash text; result jsonb; changed integer:=0;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_request_id is null or p_action is null or p_action not in ('compact','restore')
    or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or p_archive_sha256 is null or p_archive_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_packet) is distinct from 'object' or not(p_packet ?& array['id','beforeText'])
    or p_packet-array['id','beforeText']<>'{}'::jsonb or jsonb_typeof(p_packet->'beforeText') is distinct from 'string'
    or octet_length(p_packet->>'beforeText')>16777216 then
    raise exception 'reviewed_bundle_packet_invalid' using errcode='22023'; end if;
  v_release_id:=(p_packet->>'id')::uuid;
  if v_release_id is null then raise exception 'reviewed_bundle_identity_invalid' using errcode='22023'; end if;
  request_hash:=private.reviewed_bundle_row_sha256_v1(jsonb_build_array(p_action,p_target_project_ref,p_archive_sha256,p_packet));
  select * into receipt from private.reviewed_bundle_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'reviewed_bundle_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('reviewed-bundle-request:'||p_request_id,64004)) then
    raise exception 'reviewed_bundle_busy' using errcode='55P03'; end if;
  current_doc:=private.lock_reviewed_bundle_v1(v_release_id,p_target_project_ref);
  select * into receipt from private.reviewed_bundle_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'reviewed_bundle_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  select * into m from private.reviewed_bundle_archives a where a.release_id=v_release_id for update nowait;
  if not found then raise exception 'reviewed_bundle_preparation_missing' using errcode='P0002'; end if;
  before_doc:=(p_packet->>'beforeText')::jsonb;
  if private.reviewed_bundle_row_sha256_v1(before_doc) is distinct from m.original_sha256
    or before_doc->>'release_id' is distinct from v_release_id::text
    or before_doc->>'target_project_ref' is distinct from p_target_project_ref
    or private.reviewed_bundle_row_sha256_v1(before_doc->'bundle') is distinct from m.bundle_sha256 then
    raise exception 'reviewed_bundle_archive_changed' using errcode='40001'; end if;
  next_doc:=private.reviewed_bundle_compacted_row_v1(before_doc);
  if private.reviewed_bundle_row_sha256_v1(next_doc) is distinct from m.compacted_sha256 then
    raise exception 'reviewed_bundle_reference_changed' using errcode='40001'; end if;
  current_hash:=private.reviewed_bundle_row_sha256_v1(current_doc);
  if current_hash is distinct from (case when m.state='compacted' then m.compacted_sha256 else m.original_sha256 end) then
    raise exception 'reviewed_bundle_row_changed' using errcode='40001'; end if;
  if p_action='restore' then next_doc:=before_doc; end if;
  if current_doc is distinct from next_doc then
    insert into private.reviewed_bundle_write_permits values(pg_backend_pid(),txid_current(),v_release_id,current_hash,private.reviewed_bundle_row_sha256_v1(next_doc));
    update private.reviewed_mock_source_releases_v1 r set bundle=next_doc->'bundle' where r.release_id=v_release_id;
    if exists(select 1 from private.reviewed_bundle_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()) then
      raise exception 'reviewed_bundle_permit_not_consumed' using errcode='55000'; end if;
    changed:=1;
  end if;
  update private.reviewed_bundle_archives a set state=case when p_action='compact' then 'compacted' else 'restored' end
    where a.release_id=v_release_id;
  if (select private.reviewed_bundle_row_sha256_v1(to_jsonb(r)) from private.reviewed_mock_source_releases_v1 r
      where r.release_id=v_release_id) is distinct from private.reviewed_bundle_row_sha256_v1(next_doc) then
    raise exception 'reviewed_bundle_write_mismatch' using errcode='40001'; end if;
  result:=jsonb_build_object('requestId',p_request_id,'releaseId',v_release_id,'action',p_action,'changed',changed,'archiveHash',p_archive_sha256);
  insert into private.reviewed_bundle_archive_receipts(request_id,request_sha256,archive_sha256,release_id,result)
    values(p_request_id,request_hash,p_archive_sha256,v_release_id,result);
  return result;
end $$;

do $acl$
declare r record;
begin
  for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in ('reviewed_bundle_row_sha256_v1','reviewed_bundle_compacted_row_v1',
      'check_reviewed_bundle_operator_v1','lock_reviewed_bundle_v1','list_reviewed_bundle_candidates_v1',
      'prepare_reviewed_bundle_archive_v1','guard_reviewed_bundle_write_v1','apply_reviewed_bundle_archive_v1') loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);
  end loop;
end $acl$;

select set_config('search_path','public',true);
-- APP-20261003-05: reconstruct a reviewed package's entries from immutable occurrences.
-- This migration installs tools only; no existing package is compacted here.
create table private.exam_use_package_archives (
  release_id uuid primary key references private.reviewed_mock_source_releases_v1(release_id),
  target_project_ref text not null,
  source_rows integer[] not null check(cardinality(source_rows) between 4 and 2000),
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  identity_sha256 text not null check(identity_sha256 ~ '^[a-f0-9]{64}$'),
  package_sha256 text not null check(package_sha256 ~ '^[a-f0-9]{64}$'),
  header_sha256 text not null check(header_sha256 ~ '^[a-f0-9]{64}$'),
  reference_sha256 text not null check(reference_sha256 ~ '^[a-f0-9]{64}$'),
  original_lifecycle jsonb not null check(jsonb_typeof(original_lifecycle)='object'
    and original_lifecycle ?& array['status','retired_at_utc']
    and original_lifecycle-array['status','retired_at_utc']='{}'::jsonb),
  original_bytes integer not null check(original_bytes between 1 and 16777216),
  state text not null check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp()
);
create table private.exam_use_package_archive_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  release_id uuid not null references private.exam_use_package_archives(release_id),
  result jsonb not null,
  created_at timestamptz not null default clock_timestamp()
);
create table private.exam_use_package_write_permits (
  backend_pid integer not null, transaction_id bigint not null, release_id uuid not null,
  before_sha256 text not null, after_sha256 text not null,
  primary key(backend_pid,transaction_id,release_id)
);
alter table private.exam_use_package_archives enable row level security;
alter table private.exam_use_package_archive_receipts enable row level security;
alter table private.exam_use_package_write_permits enable row level security;
revoke all on private.exam_use_package_archives,private.exam_use_package_archive_receipts,private.exam_use_package_write_permits
  from public,anon,authenticated,service_role;
create trigger exam_use_package_receipt_immutable before update or delete on private.exam_use_package_archive_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

create function private.exam_use_package_reference_v1(p_release_id uuid,p_package jsonb,p_source_rows integer[]) returns jsonb
language sql immutable strict set search_path='' as $$
  select (p_package-'entries')||jsonb_build_object('__exam_use_entries_ref_v1',jsonb_build_object(
    'releaseId',p_release_id,'packageHash',private.reviewed_bundle_row_sha256_v1(p_package),
    'headerHash',private.reviewed_bundle_row_sha256_v1(p_package-'entries'),
    'sourceRowsHash',private.reviewed_bundle_row_sha256_v1(to_jsonb(p_source_rows))));
$$;

create function private.reassemble_exam_use_entries_v1(p_release_id uuid,p_header jsonb,p_source_rows integer[]) returns jsonb
language plpgsql stable set search_path='' as $$
declare entries jsonb; found_count integer;
begin
  if p_release_id is null or jsonb_typeof(p_header) is distinct from 'object'
    or p_header ?| array['entries','__exam_use_entries_ref_v1']
    or p_source_rows is null or cardinality(p_source_rows) not between 4 and 2000
    or (select count(distinct k) from unnest(p_source_rows) k)<>cardinality(p_source_rows) then
    raise exception 'exam_package_reference_invalid' using errcode='40001'; end if;
  select jsonb_agg(o.package_entry_json order by k.ordinal),count(o.source_row)
    into entries,found_count from unnest(p_source_rows) with ordinality k(source_row,ordinal)
    left join word_index.app_exam_use_occurrence o on o.release_id=p_release_id and o.source_row=k.source_row;
  if found_count<>cardinality(p_source_rows)
    or (select count(*) from word_index.app_exam_use_occurrence where release_id=p_release_id)<>found_count then
    raise exception 'exam_package_occurrences_changed' using errcode='40001'; end if;
  return p_header||jsonb_build_object('entries',entries);
end $$;

create function private.resolve_exam_use_package_json_v1(p_release_id uuid) returns jsonb
language plpgsql stable set search_path='' as $$
declare stored jsonb; rebuilt jsonb; m private.exam_use_package_archives;
begin
  select package_json into stored from word_index.app_exam_use_release where release_id=p_release_id;
  if not found then raise exception 'exam_package_missing' using errcode='P0002'; end if;
  select * into m from private.exam_use_package_archives where release_id=p_release_id;
  if not(stored ? '__exam_use_entries_ref_v1') then
    if m.state='compacted' then raise exception 'exam_package_reference_changed' using errcode='40001'; end if;
    return stored;
  end if;
  if m.release_id is null or m.state<>'compacted' or stored ? 'entries'
    or private.reviewed_bundle_row_sha256_v1(stored) is distinct from m.reference_sha256
    or private.reviewed_bundle_row_sha256_v1(stored-'__exam_use_entries_ref_v1') is distinct from m.header_sha256
    or stored->'__exam_use_entries_ref_v1' is distinct from jsonb_build_object(
      'releaseId',p_release_id,'packageHash',m.package_sha256,'headerHash',m.header_sha256,
      'sourceRowsHash',private.reviewed_bundle_row_sha256_v1(to_jsonb(m.source_rows))) then
    raise exception 'exam_package_reference_changed' using errcode='40001'; end if;
  rebuilt:=private.reassemble_exam_use_entries_v1(p_release_id,stored-'__exam_use_entries_ref_v1',m.source_rows);
  if private.reviewed_bundle_row_sha256_v1(rebuilt) is distinct from m.package_sha256 then
    raise exception 'exam_package_content_changed' using errcode='40001'; end if;
  return rebuilt;
end $$;

-- Preserve the current definitions (including M02 restoration), OIDs and ACLs.
do $consumers$
declare definition text; needle text; replacement text;
begin
  definition:=pg_get_functiondef('private.import_app_exam_use_package_core_v1(jsonb)'::regprocedure);
  needle:='existing_release.package_json <> p_package';
  replacement:='private.resolve_exam_use_package_json_v1(existing_release.release_id) <> p_package';
  if (length(definition)-length(replace(definition,needle,'')))/length(needle)<>1 then
    raise exception 'exam_package_import_consumer_drift'; end if;
  execute replace(definition,needle,replacement);
  definition:=pg_get_functiondef('private.current_wrong_review_material_fingerprint_v1(uuid,jsonb,uuid[])'::regprocedure);
  needle:='select to_jsonb(r) from word_index.app_exam_use_release r where r.release_id=active_release';
  replacement:='select jsonb_set(to_jsonb(r),''{package_json}'',private.resolve_exam_use_package_json_v1(r.release_id)) from word_index.app_exam_use_release r where r.release_id=active_release';
  if (length(definition)-length(replace(definition,needle,'')))/length(needle)<>1 then
    raise exception 'exam_package_fingerprint_consumer_drift'; end if;
  execute replace(definition,needle,replacement);
end $consumers$;

create function private.lock_exam_use_package_v1(p_release_id uuid,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare v_dataset_id uuid; v_dataset_key text; v_project_ref text; doc jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_release_id is null or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then
    raise exception 'exam_package_identity_invalid' using errcode='22023'; end if;
  select r.dataset_id,a.dataset_key,r.target_project_ref into v_dataset_id,v_dataset_key,v_project_ref
    from private.reviewed_mock_source_releases_v1 r join private.reviewed_mock_source_approvals_v1 a
      on a.approval_id=r.approval_id and a.target_project_ref=r.target_project_ref where r.release_id=p_release_id;
  if not found then raise exception 'exam_package_reviewed_source_required' using errcode='P0002'; end if;
  if v_project_ref<>p_target_project_ref then raise exception 'exam_package_project_mismatch' using errcode='22023'; end if;
  if v_dataset_key='g12-long-reading-2025-exam-scope-v1' then raise exception 'exam_package_catalog_source_excluded' using errcode='22023'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended(v_dataset_key,9129)) then
    raise exception 'exam_package_busy' using errcode='55P03'; end if;
  -- Same parent order as wrong-review fingerprint/save, with immediate failure.
  perform id from public.vocab_datasets where id=v_dataset_id for update nowait;
  select to_jsonb(r) into doc from word_index.app_exam_use_release r
    where r.release_id=p_release_id and r.dataset_id=v_dataset_id for update nowait;
  if not found then raise exception 'exam_package_missing' using errcode='P0002'; end if;
  perform source_row from word_index.app_exam_use_occurrence where release_id=p_release_id order by source_row for share nowait;
  return doc;
end $$;

create function private.list_exam_use_package_candidates_v1(p_target_project_ref text) returns jsonb
language plpgsql set search_path='' as $$
declare result jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then
    raise exception 'exam_package_identity_invalid' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('releaseId',r.release_id,'packageVersion',r.package_version) order by r.release_id),'[]')
    into result from word_index.app_exam_use_release r join private.reviewed_mock_source_releases_v1 s on s.release_id=r.release_id
    left join private.exam_use_package_archives m on m.release_id=r.release_id
    where s.target_project_ref=p_target_project_ref and r.dataset_key<>'g12-long-reading-2025-exam-scope-v1'
      and (m.release_id is null or m.state<>'compacted') and jsonb_typeof(r.package_json->'entries')='array';
  return result;
end $$;

create function private.prepare_exam_use_package_archive_v1(p_release_id uuid,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare doc jsonb; p jsonb; ordered_rows integer[]; rebuilt jsonb; reference jsonb; original_text text; approved_version text;
  m private.exam_use_package_archives;
begin
  doc:=private.lock_exam_use_package_v1(p_release_id,p_target_project_ref);
  select * into m from private.exam_use_package_archives where release_id=p_release_id for update nowait;
  if found then
    if m.state='compacted' then raise exception 'exam_package_archive_file_required' using errcode='22023'; end if;
    if m.target_project_ref<>p_target_project_ref
      or private.reviewed_bundle_row_sha256_v1(doc-array['package_json','status','retired_at_utc']) is distinct from m.identity_sha256
      or private.reviewed_bundle_row_sha256_v1(doc->'package_json') is distinct from m.package_sha256 then
      raise exception 'exam_package_row_changed' using errcode='40001'; end if;
    -- A committed prepare whose reply/file write was lost can be retried.
    -- Recreate its exact original row without reverting live retirement state.
    doc:=doc||m.original_lifecycle;
    if private.reviewed_bundle_row_sha256_v1(doc) is distinct from m.original_sha256 then
      raise exception 'exam_package_archive_changed' using errcode='40001'; end if;
    return jsonb_build_object('id',p_release_id,'projectRef',p_target_project_ref,'beforeText',doc::text);
  end if;
  p:=doc->'package_json';
  if p ? '__exam_use_entries_ref_v1' or p->>'package_type' is distinct from 'student-app-exam-use-wordbook'
    or p->>'schema_version' is distinct from '1.0' or jsonb_typeof(p->'entries') is distinct from 'array'
    or jsonb_array_length(p->'entries') not between 4 and 2000 then
    raise exception 'exam_package_source_invalid' using errcode='22023'; end if;
  original_text:=doc::text;
  if octet_length(original_text)>16777216 then raise exception 'exam_package_row_too_large' using errcode='22023'; end if;
  select a.package_version into approved_version from private.reviewed_mock_source_releases_v1 r
    join private.reviewed_mock_source_approvals_v1 a on a.approval_id=r.approval_id and a.target_project_ref=r.target_project_ref
    where r.release_id=p_release_id;
  if p->>'package_version' is distinct from approved_version or doc->>'package_version' is distinct from approved_version
    or private.reviewed_exam_sha256_v1(p-'package_version') is distinct from approved_version then
    raise exception 'exam_package_approval_changed' using errcode='40001'; end if;
  if exists(select 1 from jsonb_array_elements(p->'entries') e
      where jsonb_typeof(e->'source_row') is distinct from 'number' or e->>'source_row' !~ '^[1-9][0-9]{0,8}$') then
    raise exception 'exam_package_source_rows_invalid' using errcode='22023'; end if;
  select array_agg((e.value->>'source_row')::integer order by e.ordinal)
    into ordered_rows from jsonb_array_elements(p->'entries') with ordinality e(value,ordinal);
  rebuilt:=private.reassemble_exam_use_entries_v1(p_release_id,p-'entries',ordered_rows);
  if rebuilt is distinct from p then raise exception 'exam_package_occurrences_changed' using errcode='40001'; end if;
  reference:=private.exam_use_package_reference_v1(p_release_id,p,ordered_rows);
  insert into private.exam_use_package_archives(release_id,target_project_ref,source_rows,original_sha256,identity_sha256,
    package_sha256,header_sha256,reference_sha256,original_lifecycle,original_bytes,state)
    values(p_release_id,p_target_project_ref,ordered_rows,private.reviewed_bundle_row_sha256_v1(doc),
      private.reviewed_bundle_row_sha256_v1(doc-array['package_json','status','retired_at_utc']),
      private.reviewed_bundle_row_sha256_v1(p),private.reviewed_bundle_row_sha256_v1(p-'entries'),
      private.reviewed_bundle_row_sha256_v1(reference),jsonb_build_object('status',doc->'status','retired_at_utc',doc->'retired_at_utc'),
      octet_length(original_text),'prepared');
  return jsonb_build_object('id',p_release_id,'projectRef',p_target_project_ref,'beforeText',original_text);
end $$;

create function private.guard_exam_use_package_write_v1() returns trigger
language plpgsql security definer set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
begin
  -- Preserve the former release-specific branch of the common source guard.
  if tg_op='UPDATE' then
    if to_jsonb(new)-array['status','retired_at_utc']=to_jsonb(old)-array['status','retired_at_utc'] then return new; end if;
    if to_jsonb(new)-'package_json'=to_jsonb(old)-'package_json' then
      delete from private.exam_use_package_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()
        and release_id=old.release_id and before_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(old))
        and after_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(new));
      if found then return new; end if;
    end if;
  end if;
  if exists(select 1 from private.reviewed_mock_source_releases_v1 where release_id=old.release_id) then
    raise exception 'reviewed_mock_source_immutable' using errcode='22023'; end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;
drop trigger reviewed_mock_source_release_immutable on word_index.app_exam_use_release;
create trigger reviewed_mock_source_release_immutable before update or delete on word_index.app_exam_use_release
  for each row execute function private.guard_exam_use_package_write_v1();

create function private.apply_exam_use_package_archive_v1(p_request_id uuid,p_action text,p_target_project_ref text,p_archive_sha256 text,p_packet jsonb)
returns jsonb language plpgsql set search_path='' set TimeZone='UTC' set DateStyle='ISO, MDY' as $$
declare request_hash text; receipt private.exam_use_package_archive_receipts; m private.exam_use_package_archives;
  v_release_id uuid; before_doc jsonb; current_doc jsonb; next_doc jsonb; reference jsonb; rebuilt jsonb; result jsonb; changed integer:=0;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_request_id is null or p_action is null or p_action not in ('compact','restore')
    or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or p_archive_sha256 is null or p_archive_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_packet) is distinct from 'object' or not(p_packet ?& array['id','projectRef','beforeText'])
    or p_packet-array['id','projectRef','beforeText']<>'{}'::jsonb
    or jsonb_typeof(p_packet->'beforeText') is distinct from 'string'
    or octet_length(p_packet->>'beforeText')>16777216 then
    raise exception 'exam_package_packet_invalid' using errcode='22023'; end if;
  v_release_id:=(p_packet->>'id')::uuid;
  if v_release_id is null or p_packet->>'projectRef' is distinct from p_target_project_ref then
    raise exception 'exam_package_project_mismatch' using errcode='22023'; end if;
  request_hash:=private.reviewed_bundle_row_sha256_v1(jsonb_build_array(p_action,p_target_project_ref,p_archive_sha256,p_packet));
  select * into receipt from private.exam_use_package_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'exam_package_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('exam-package-request:'||p_request_id,64005)) then
    raise exception 'exam_package_busy' using errcode='55P03'; end if;
  current_doc:=private.lock_exam_use_package_v1(v_release_id,p_target_project_ref);
  select * into receipt from private.exam_use_package_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'exam_package_request_reused' using errcode='40001'; end if;
    return receipt.result;
  end if;
  select * into m from private.exam_use_package_archives where release_id=v_release_id for update nowait;
  if not found then raise exception 'exam_package_preparation_missing' using errcode='P0002'; end if;
  before_doc:=(p_packet->>'beforeText')::jsonb;
  if m.target_project_ref<>p_target_project_ref or before_doc->>'release_id' is distinct from v_release_id::text
    or private.reviewed_bundle_row_sha256_v1(before_doc) is distinct from m.original_sha256
    or private.reviewed_bundle_row_sha256_v1(before_doc->'package_json') is distinct from m.package_sha256 then
    raise exception 'exam_package_archive_changed' using errcode='40001'; end if;
  reference:=private.exam_use_package_reference_v1(v_release_id,before_doc->'package_json',m.source_rows);
  if private.reviewed_bundle_row_sha256_v1(reference) is distinct from m.reference_sha256
    or private.reviewed_bundle_row_sha256_v1((before_doc->'package_json')-'entries') is distinct from m.header_sha256 then
    raise exception 'exam_package_reference_changed' using errcode='40001'; end if;
  if private.reviewed_bundle_row_sha256_v1(current_doc-array['package_json','status','retired_at_utc']) is distinct from m.identity_sha256
    or private.reviewed_bundle_row_sha256_v1(current_doc->'package_json') is distinct from
      (case when m.state='compacted' then m.reference_sha256 else m.package_sha256 end) then
    raise exception 'exam_package_row_changed' using errcode='40001'; end if;
  if p_action='compact' then
    rebuilt:=private.reassemble_exam_use_entries_v1(v_release_id,(before_doc->'package_json')-'entries',m.source_rows);
    if private.reviewed_bundle_row_sha256_v1(rebuilt) is distinct from m.package_sha256 then
      raise exception 'exam_package_occurrences_changed' using errcode='40001'; end if;
    next_doc:=jsonb_set(current_doc,'{package_json}',reference);
  else
    -- Restore the saved body only; preserve current retirement/status values.
    next_doc:=jsonb_set(current_doc,'{package_json}',before_doc->'package_json');
  end if;
  if current_doc is distinct from next_doc then
    insert into private.exam_use_package_write_permits values(pg_backend_pid(),txid_current(),v_release_id,
      private.reviewed_bundle_row_sha256_v1(current_doc),private.reviewed_bundle_row_sha256_v1(next_doc));
    update word_index.app_exam_use_release set package_json=next_doc->'package_json' where release_id=v_release_id;
    if exists(select 1 from private.exam_use_package_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()) then
      raise exception 'exam_package_permit_not_consumed' using errcode='55000'; end if;
    changed:=1;
  end if;
  update private.exam_use_package_archives set state=case when p_action='compact' then 'compacted' else 'restored' end where release_id=v_release_id;
  if (select private.reviewed_bundle_row_sha256_v1(to_jsonb(r)) from word_index.app_exam_use_release r where release_id=v_release_id)
      is distinct from private.reviewed_bundle_row_sha256_v1(next_doc)
    or private.resolve_exam_use_package_json_v1(v_release_id) is distinct from before_doc->'package_json' then
    raise exception 'exam_package_write_mismatch' using errcode='40001'; end if;
  result:=jsonb_build_object('requestId',p_request_id,'releaseId',v_release_id,'action',p_action,'changed',changed,'archiveHash',p_archive_sha256);
  insert into private.exam_use_package_archive_receipts(request_id,request_sha256,archive_sha256,release_id,result)
    values(p_request_id,request_hash,p_archive_sha256,v_release_id,result);
  return result;
end $$;

do $acl$
declare f record;
begin
  for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='private' and p.proname in ('exam_use_package_reference_v1','reassemble_exam_use_entries_v1',
      'resolve_exam_use_package_json_v1','lock_exam_use_package_v1','list_exam_use_package_candidates_v1',
      'prepare_exam_use_package_archive_v1','guard_exam_use_package_write_v1','apply_exam_use_package_archive_v1') loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  end loop;
end $acl$;

select set_config('search_path','public',true);
-- APP-20261003-06: share a reviewed occurrence's duplicate entry through its fixed columns.
-- Installs tools only. Existing source rows are not changed by this migration.
create table private.exam_use_occurrence_archives (
  release_id uuid not null, source_row integer not null,
  target_project_ref text not null,
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  identity_sha256 text not null check(identity_sha256 ~ '^[a-f0-9]{64}$'),
  entry_sha256 text not null check(entry_sha256 ~ '^[a-f0-9]{64}$'),
  reference_sha256 text not null check(reference_sha256 ~ '^[a-f0-9]{64}$'),
  original_bytes integer not null check(original_bytes between 1 and 1048576),
  state text not null check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp(),
  primary key(release_id,source_row),
  foreign key(release_id,source_row) references word_index.app_exam_use_occurrence(release_id,source_row)
);
create table private.exam_use_occurrence_archive_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  result jsonb not null, created_at timestamptz not null default clock_timestamp()
);
create table private.exam_use_occurrence_write_permits (
  backend_pid integer not null, transaction_id bigint not null,
  release_id uuid not null, source_row integer not null,
  before_sha256 text not null, after_sha256 text not null,
  primary key(backend_pid,transaction_id,release_id,source_row)
);
alter table private.exam_use_occurrence_archives enable row level security;
alter table private.exam_use_occurrence_archive_receipts enable row level security;
alter table private.exam_use_occurrence_write_permits enable row level security;
revoke all on private.exam_use_occurrence_archives,private.exam_use_occurrence_archive_receipts,private.exam_use_occurrence_write_permits from public,anon,authenticated,service_role;
create trigger exam_use_occurrence_receipt_immutable before update or delete on private.exam_use_occurrence_archive_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

create function private.exam_use_occurrence_entry_fields_v1() returns text[]
language sql immutable set search_path='' as $$ select array['source_row','position_in_unit','dictionary_id','legacy_ids','sense_id','pronunciation_variant_id','display_headword','display_gloss_ko','display_pronunciation_ko','display_pronunciation_review_status','audio','occurrence_id','occurrence_content_hash','content_hash','exam_review_id','exam_input_hash','exam_use_status','context_evidence_status','context_evidence','entry_row_sha256','source_entry_id','source_entry_sha256','include_in_exam','manual_review_flags']; $$;

create function private.exam_use_occurrence_entry_candidates_v1(p_row jsonb) returns jsonb
language sql immutable strict set search_path='' as $$
  select jsonb_build_object('source_row',p_row->'source_row',
    'position_in_unit',p_row->'position_in_unit',
    'dictionary_id',p_row->'dictionary_id',
    'legacy_ids',p_row->'legacy_ids',
    'sense_id',p_row->'sense_id',
    'pronunciation_variant_id',p_row->'pronunciation_variant_id',
    'display_headword',p_row->'display_headword',
    'display_gloss_ko',p_row->'display_gloss_ko',
    'display_pronunciation_ko',p_row->'display_pronunciation_ko',
    'display_pronunciation_review_status',p_row->'display_pronunciation_review_status',
    'audio',p_row->'audio_json',
    'occurrence_id',p_row->'occurrence_id',
    'occurrence_content_hash',p_row->'occurrence_content_hash',
    'content_hash',p_row->'package_entry_content_hash',
    'exam_review_id',p_row->'exam_review_id',
    'exam_input_hash',p_row->'exam_input_hash',
    'exam_use_status',p_row->'exam_use_status',
    'context_evidence_status',p_row->'context_evidence_status',
    'context_evidence',p_row->'context_evidence',
    'entry_row_sha256',p_row->'source_projection_row_sha256',
    'source_entry_id',p_row->'source_entry_id',
    'source_entry_sha256',p_row->'source_entry_sha256',
    'include_in_exam',p_row->'include_in_exam',
    'manual_review_flags',p_row->'manual_review_flags');
$$;

create function private.exam_use_occurrence_entry_reference_v1(p_row jsonb) returns jsonb
language plpgsql immutable strict set search_path='' as $$
declare original jsonb:=p_row->'package_entry_json'; candidates jsonb; extra jsonb; result jsonb;
  field_names text[]:=private.exam_use_occurrence_entry_fields_v1(); field_name text; mask integer:=0; i integer;
begin
  if jsonb_typeof(original) is distinct from 'object' or original ? '__exam_use_entry_ref_v1'
    or not(p_row ?& array['release_id','source_row']) then
    raise exception 'occurrence_entry_original_invalid' using errcode='22023'; end if;
  candidates:=private.exam_use_occurrence_entry_candidates_v1(p_row);extra:=original;
  for i in 1..cardinality(field_names) loop
    field_name:=field_names[i];
    -- jsonb equality treats 1 and 1.0 as equal; the legacy text SHA does not.
    if original ? field_name and (original->field_name)::text=(candidates->field_name)::text then
      mask:=mask | (1 << (i-1));extra:=extra-field_name;
    end if;
  end loop;
  if octet_length(extra::text)>4096 then raise exception 'occurrence_entry_residual_too_large' using errcode='22023'; end if;
  result:=jsonb_build_object('__exam_use_entry_ref_v1',jsonb_build_object(
    'releaseId',p_row->'release_id','sourceRow',p_row->'source_row','fields',mask),'extra',extra);
  if octet_length(result::text)>=octet_length(original::text) then
    raise exception 'occurrence_entry_not_smaller' using errcode='22023'; end if;
  return result;
end $$;

create function private.restore_exam_use_occurrence_v1(p_row jsonb) returns jsonb
language plpgsql stable strict set search_path='' as $$
declare stored jsonb:=p_row->'package_entry_json'; m private.exam_use_occurrence_archives; rebuilt jsonb; original jsonb;
  candidates jsonb; field_names text[]:=private.exam_use_occurrence_entry_fields_v1(); mask integer; i integer;
begin
  select * into m from private.exam_use_occurrence_archives where release_id=(p_row->>'release_id')::uuid and source_row=(p_row->>'source_row')::integer;
  if not(stored ? '__exam_use_entry_ref_v1') then
    if m.state='compacted' then raise exception 'occurrence_entry_reference_changed' using errcode='40001'; end if;
    return p_row;
  end if;
  if m.release_id is null or m.state<>'compacted'
    or private.reviewed_bundle_row_sha256_v1(p_row-'package_entry_json') is distinct from m.identity_sha256
    or private.reviewed_bundle_row_sha256_v1(stored) is distinct from m.reference_sha256 then
    raise exception 'occurrence_entry_reference_changed' using errcode='40001'; end if;
  if jsonb_typeof(stored->'extra') is distinct from 'object'
    or stored#>'{__exam_use_entry_ref_v1,releaseId}' is distinct from p_row->'release_id'
    or stored#>'{__exam_use_entry_ref_v1,sourceRow}' is distinct from p_row->'source_row'
    or jsonb_typeof(stored#>'{__exam_use_entry_ref_v1,fields}') is distinct from 'number'
    or stored#>>'{__exam_use_entry_ref_v1,fields}' !~ '^[0-9]{1,8}$' then
    raise exception 'occurrence_entry_reference_invalid' using errcode='40001'; end if;
  mask:=(stored#>>'{__exam_use_entry_ref_v1,fields}')::integer;
  if mask<0 or mask>=(1 << cardinality(field_names)) then raise exception 'occurrence_entry_reference_invalid' using errcode='40001'; end if;
  candidates:=private.exam_use_occurrence_entry_candidates_v1(p_row);rebuilt:=stored->'extra';
  for i in 1..cardinality(field_names) loop
    if (mask & (1 << (i-1)))<>0 then
      if rebuilt ? field_names[i] then raise exception 'occurrence_entry_reference_invalid' using errcode='40001'; end if;
      rebuilt:=rebuilt||jsonb_build_object(field_names[i],candidates->field_names[i]);
    end if;
  end loop;
  original:=jsonb_set(p_row,'{package_entry_json}',rebuilt);
  if private.reviewed_bundle_row_sha256_v1(rebuilt) is distinct from m.entry_sha256
    or private.reviewed_bundle_row_sha256_v1(original) is distinct from m.original_sha256
    or private.exam_use_occurrence_entry_reference_v1(original) is distinct from stored then
    raise exception 'occurrence_entry_content_changed' using errcode='40001'; end if;
  return original;
end $$;

create function private.lock_exam_use_occurrences_v1(p_keys jsonb,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' as $$
declare item record; result jsonb; key_count integer;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or jsonb_typeof(p_keys) is distinct from 'array' or jsonb_array_length(p_keys) not between 1 and 100
    or exists(select 1 from jsonb_array_elements(p_keys) k where jsonb_typeof(k) is distinct from 'object'
      or not(k ?& array['releaseId','sourceRow']) or k-array['releaseId','sourceRow']<>'{}'
      or jsonb_typeof(k->'releaseId') is distinct from 'string'
      or jsonb_typeof(k->'sourceRow') is distinct from 'number' or k->>'sourceRow' !~ '^[1-9][0-9]{0,8}$') then
    raise exception 'occurrence_entry_keys_invalid' using errcode='22023'; end if;
  key_count:=jsonb_array_length(p_keys);
  if (select count(distinct ((k->>'releaseId')::uuid,(k->>'sourceRow')::integer)) from jsonb_array_elements(p_keys) k)<>key_count then
    raise exception 'occurrence_entry_duplicate_key' using errcode='22023'; end if;
  if (select count(*) from jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer)
    join word_index.app_exam_use_occurrence o on o.release_id=k."releaseId" and o.source_row=k."sourceRow"
    join private.reviewed_mock_source_releases_v1 s on s.release_id=o.release_id
    join private.reviewed_mock_source_approvals_v1 a on a.approval_id=s.approval_id and a.target_project_ref=s.target_project_ref
    where s.target_project_ref=p_target_project_ref and a.package_version=(select package_version from word_index.app_exam_use_release where release_id=s.release_id)
      and a.dataset_key<>'g12-long-reading-2025-exam-scope-v1')<>key_count then
    raise exception 'occurrence_entry_reviewed_source_required' using errcode='P0002'; end if;
  for item in select distinct r.dataset_key,r.dataset_id,r.release_id from word_index.app_exam_use_release r
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=r.release_id
    order by r.dataset_key,r.release_id loop
    if not pg_try_advisory_xact_lock(hashtextextended(item.dataset_key,9129)) then raise exception 'occurrence_entry_busy' using errcode='55P03'; end if;
    perform 1 from public.vocab_datasets where id=item.dataset_id for update nowait;
    perform 1 from word_index.app_exam_use_release where release_id=item.release_id for update nowait;
  end loop;
  perform 1 from word_index.app_exam_use_occurrence o
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=o.release_id and k."sourceRow"=o.source_row
    order by o.release_id,o.source_row for update of o nowait;
  select jsonb_agg(to_jsonb(o) order by o.release_id,o.source_row) into result from word_index.app_exam_use_occurrence o
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=o.release_id and k."sourceRow"=o.source_row;
  if jsonb_array_length(result) is distinct from key_count then raise exception 'occurrence_entry_row_changed' using errcode='40001'; end if;
  return result;
end $$;

create function private.list_exam_use_occurrence_candidates_v1(p_target_project_ref text,p_release_id uuid default null) returns jsonb
language plpgsql set search_path='' as $$
declare result jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then raise exception 'occurrence_entry_project_invalid' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('releaseId',o.release_id,'sourceRow',o.source_row) order by o.release_id,o.source_row),'[]') into result
    from word_index.app_exam_use_occurrence o join private.reviewed_mock_source_releases_v1 s on s.release_id=o.release_id
    join word_index.app_exam_use_release r on r.release_id=o.release_id
    left join private.exam_use_occurrence_archives m on m.release_id=o.release_id and m.source_row=o.source_row
    where s.target_project_ref=p_target_project_ref and (p_release_id is null or o.release_id=p_release_id)
      and r.dataset_key<>'g12-long-reading-2025-exam-scope-v1' and (m.release_id is null or m.state<>'compacted');
  return result;
end $$;

create function private.prepare_exam_use_occurrence_archive_v1(p_keys jsonb,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' as $$
declare rows jsonb; row_doc jsonb; original_text text; reference jsonb; m private.exam_use_occurrence_archives; packets jsonb:='[]'; answer jsonb;
begin
  rows:=private.lock_exam_use_occurrences_v1(p_keys,p_target_project_ref);
  for row_doc in select value from jsonb_array_elements(rows) loop
    select * into m from private.exam_use_occurrence_archives where release_id=(row_doc->>'release_id')::uuid and source_row=(row_doc->>'source_row')::int for update nowait;
    original_text:=row_doc::text;
    if found then
      if m.target_project_ref<>p_target_project_ref then raise exception 'occurrence_entry_project_mismatch' using errcode='22023'; end if;
      if m.state='compacted' then raise exception 'occurrence_entry_archive_file_required' using errcode='22023'; end if;
      if private.reviewed_bundle_row_sha256_v1(row_doc) is distinct from m.original_sha256 then raise exception 'occurrence_entry_row_changed' using errcode='40001'; end if;
    else
      if octet_length(original_text)>1048576 then raise exception 'occurrence_entry_row_too_large' using errcode='22023'; end if;
      reference:=private.exam_use_occurrence_entry_reference_v1(row_doc);
      insert into private.exam_use_occurrence_archives(release_id,source_row,target_project_ref,original_sha256,identity_sha256,entry_sha256,reference_sha256,original_bytes,state)
      values((row_doc->>'release_id')::uuid,(row_doc->>'source_row')::int,p_target_project_ref,
        private.reviewed_bundle_row_sha256_v1(row_doc),private.reviewed_bundle_row_sha256_v1(row_doc-'package_entry_json'),
        private.reviewed_bundle_row_sha256_v1(row_doc->'package_entry_json'),private.reviewed_bundle_row_sha256_v1(reference),octet_length(original_text),'prepared');
    end if;
    packets:=packets||jsonb_build_array(jsonb_build_object('releaseId',row_doc->'release_id','sourceRow',row_doc->'source_row','beforeText',original_text));
  end loop;
  answer:=jsonb_build_object('projectRef',p_target_project_ref,'rows',packets);
  if octet_length(answer::text)>16777216 then raise exception 'occurrence_entry_batch_too_large' using errcode='22023'; end if;
  return answer;
end $$;

create function private.guard_exam_use_occurrence_write_v1() returns trigger
language plpgsql security definer set search_path='' as $$
declare dataset uuid;
begin
  if tg_op='UPDATE' and to_jsonb(new)-'package_entry_json'=to_jsonb(old)-'package_entry_json' then
    delete from private.exam_use_occurrence_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()
      and release_id=old.release_id and source_row=old.source_row
      and before_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(old)) and after_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(new));
    if found then return new; end if;
  end if;
  -- Exact original occurrence branch of the shared reviewed-source guard.
  if tg_op='INSERT' then dataset:=new.dataset_id; else dataset:=old.dataset_id; end if;
  if tg_op='UPDATE' and exists(select 1 from private.reviewed_mock_source_releases_v1 where dataset_id=new.dataset_id) then
    raise exception 'reviewed_mock_source_immutable'; end if;
  if exists(select 1 from private.reviewed_mock_source_releases_v1 where dataset_id=dataset) then raise exception 'reviewed_mock_source_immutable'; end if;
  if tg_op<>'DELETE' and new.package_entry_json ? '__exam_use_entry_ref_v1' then raise exception 'occurrence_entry_reserved_marker' using errcode='22023'; end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;
-- Refuse to reinterpret pre-existing arbitrary input as the new storage format.
do $$begin
  if exists(select 1 from word_index.app_exam_use_occurrence where package_entry_json ? '__exam_use_entry_ref_v1') then
    raise exception 'occurrence_entry_reserved_marker_exists'; end if;
end$$;
drop trigger reviewed_mock_occurrence_immutable on word_index.app_exam_use_occurrence;
create trigger reviewed_mock_occurrence_immutable before insert or update or delete on word_index.app_exam_use_occurrence
  for each row execute function private.guard_exam_use_occurrence_write_v1();

create function private.apply_exam_use_occurrence_archive_v1(p_request_id uuid,p_action text,p_target_project_ref text,p_archive_sha256 text,p_packet jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare request_hash text; receipt private.exam_use_occurrence_archive_receipts; keys jsonb; locked_rows jsonb; packet_row jsonb;
  original jsonb; current_doc jsonb; next_doc jsonb; reference jsonb; m private.exam_use_occurrence_archives; result jsonb; changed integer:=0;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_request_id is null or p_action is null or p_action not in ('compact','restore')
    or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or p_archive_sha256 is null or p_archive_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_packet) is distinct from 'object' or not(p_packet ?& array['projectRef','rows']) or p_packet-array['projectRef','rows']<>'{}'
    or p_packet->>'projectRef' is distinct from p_target_project_ref
    or jsonb_typeof(p_packet->'rows') is distinct from 'array' or jsonb_array_length(p_packet->'rows') not between 1 and 100
    or octet_length(p_packet::text)>16777216 or exists(select 1 from jsonb_array_elements(p_packet->'rows') x where jsonb_typeof(x) is distinct from 'object'
      or not(x ?& array['releaseId','sourceRow','beforeText']) or x-array['releaseId','sourceRow','beforeText']<>'{}'
      or jsonb_typeof(x->'beforeText') is distinct from 'string' or octet_length(x->>'beforeText')>1048576) then
    raise exception 'occurrence_entry_packet_invalid' using errcode='22023'; end if;
  request_hash:=private.reviewed_bundle_row_sha256_v1(jsonb_build_array(p_action,p_target_project_ref,p_archive_sha256,p_packet));
  select * into receipt from private.exam_use_occurrence_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'occurrence_entry_request_reused' using errcode='40001'; end if;return receipt.result;
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('occurrence-entry-request:'||p_request_id,64006)) then raise exception 'occurrence_entry_busy' using errcode='55P03'; end if;
  select jsonb_agg(x-'beforeText') into keys from jsonb_array_elements(p_packet->'rows') x;
  locked_rows:=private.lock_exam_use_occurrences_v1(keys,p_target_project_ref);
  select * into receipt from private.exam_use_occurrence_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'occurrence_entry_request_reused' using errcode='40001'; end if;return receipt.result;
  end if;
  for packet_row in select x from jsonb_array_elements(p_packet->'rows') x order by (x->>'releaseId')::uuid,(x->>'sourceRow')::int loop
    original:=(packet_row->>'beforeText')::jsonb;
    select * into m from private.exam_use_occurrence_archives where release_id=(packet_row->>'releaseId')::uuid and source_row=(packet_row->>'sourceRow')::int for update nowait;
    if not found then raise exception 'occurrence_entry_preparation_missing' using errcode='P0002'; end if;
    if m.target_project_ref<>p_target_project_ref or original->>'release_id' is distinct from m.release_id::text
      or (original->>'source_row')::int is distinct from m.source_row
      or private.reviewed_bundle_row_sha256_v1(original) is distinct from m.original_sha256
      or private.reviewed_bundle_row_sha256_v1(original->'package_entry_json') is distinct from m.entry_sha256 then
      raise exception 'occurrence_entry_archive_changed' using errcode='40001'; end if;
    select d into current_doc from jsonb_array_elements(locked_rows) d where d->>'release_id'=m.release_id::text and (d->>'source_row')::int=m.source_row;
    if private.reviewed_bundle_row_sha256_v1(current_doc-'package_entry_json') is distinct from m.identity_sha256
      or private.reviewed_bundle_row_sha256_v1(current_doc->'package_entry_json') is distinct from
        (case when m.state='compacted' then m.reference_sha256 else m.entry_sha256 end) then
      raise exception 'occurrence_entry_row_changed' using errcode='40001'; end if;
    reference:=private.exam_use_occurrence_entry_reference_v1(original);
    if private.reviewed_bundle_row_sha256_v1(reference) is distinct from m.reference_sha256 then raise exception 'occurrence_entry_reference_changed' using errcode='40001'; end if;
    next_doc:=jsonb_set(current_doc,'{package_entry_json}',case when p_action='compact' then reference else original->'package_entry_json' end);
    if current_doc is distinct from next_doc then
      insert into private.exam_use_occurrence_write_permits(backend_pid,transaction_id,release_id,source_row,before_sha256,after_sha256)
      values(pg_backend_pid(),txid_current(),m.release_id,m.source_row,private.reviewed_bundle_row_sha256_v1(current_doc),private.reviewed_bundle_row_sha256_v1(next_doc));
      update word_index.app_exam_use_occurrence set package_entry_json=next_doc->'package_entry_json' where release_id=m.release_id and source_row=m.source_row;
      if exists(select 1 from private.exam_use_occurrence_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current() and release_id=m.release_id and source_row=m.source_row) then
        raise exception 'occurrence_entry_permit_not_consumed' using errcode='40001'; end if;
      changed:=changed+1;
    end if;
    update private.exam_use_occurrence_archives set state=case when p_action='compact' then 'compacted' else 'restored' end where release_id=m.release_id and source_row=m.source_row;
    select to_jsonb(o) into current_doc from word_index.app_exam_use_occurrence o where release_id=m.release_id and source_row=m.source_row;
    if private.reviewed_bundle_row_sha256_v1(current_doc) is distinct from private.reviewed_bundle_row_sha256_v1(next_doc)
      or private.reviewed_bundle_row_sha256_v1(private.restore_exam_use_occurrence_v1(current_doc)) is distinct from m.original_sha256 then
      raise exception 'occurrence_entry_roundtrip_failed' using errcode='40001'; end if;
  end loop;
  result:=jsonb_build_object('requestId',p_request_id,'action',p_action,'rows',jsonb_array_length(p_packet->'rows'),'changed',changed,'archiveHash',p_archive_sha256,'keysHash',private.reviewed_bundle_row_sha256_v1(keys));
  insert into private.exam_use_occurrence_archive_receipts(request_id,request_sha256,archive_sha256,result) values(p_request_id,request_hash,p_archive_sha256,result);
  return result;
end $$;

-- Preserve every current function contract and all earlier M01/M02/APP03/APP05 fixes.
do $consumers$
declare patch record; definition text;
begin
  for patch in select * from (values
    ('private.reassemble_exam_use_entries_v1(uuid,jsonb,integer[])','jsonb_agg(o.package_entry_json order by k.ordinal)','jsonb_agg(private.restore_exam_use_occurrence_v1(to_jsonb(o))->''package_entry_json'' order by k.ordinal)'),
    ('private.current_wrong_review_material_fingerprint_v1(uuid,jsonb,uuid[])','jsonb_agg(to_jsonb(o) order by o.vocab_entry_id)','jsonb_agg(private.restore_exam_use_occurrence_v1(to_jsonb(o)) order by o.vocab_entry_id)'),
    ('private.mock_wordbook_source_version(uuid,uuid,jsonb,text)','''occurrence'', to_jsonb(o), ''entry'', to_jsonb(e)','''occurrence'', private.restore_exam_use_occurrence_v1(to_jsonb(o)), ''entry'', to_jsonb(e)'),
    ('private.vocabulary_library_source_state_values_v1(uuid,uuid,uuid,text,uuid,text)','private.vocabulary_source_snapshot_matches_v2(r.occurrence_snapshot,to_jsonb(o))','private.vocabulary_source_snapshot_matches_v2(r.occurrence_snapshot,private.restore_exam_use_occurrence_v1(to_jsonb(o)))'),
    ('private.vocabulary_library_source_states_v1(uuid[])','private.vocabulary_source_snapshot_matches_v2(r.occurrence_snapshot,to_jsonb(o))','private.vocabulary_source_snapshot_matches_v2(r.occurrence_snapshot,private.restore_exam_use_occurrence_v1(to_jsonb(o)))'),
    ('private.import_vocabulary_library_core_v1(text,text)','eid:=o.vocab_entry_id; occurrence:=to_jsonb(o);','eid:=o.vocab_entry_id; occurrence:=private.restore_exam_use_occurrence_v1(to_jsonb(o));'),
    ('public.create_mock_wordbook_composition_v1(jsonb)','for original in select * from word_index.app_exam_use_occurrence where release_id=scope.source_release_id and unit_id=scope.source_unit_id order by source_row loop','for original in select * from word_index.app_exam_use_occurrence where release_id=scope.source_release_id and unit_id=scope.source_unit_id order by source_row loop
      original:=jsonb_populate_record(null::word_index.app_exam_use_occurrence,private.restore_exam_use_occurrence_v1(to_jsonb(original)));')
  ) v(signature,needle,replacement) loop
    definition:=pg_get_functiondef(patch.signature::regprocedure);
    if (length(definition)-length(replace(definition,patch.needle,'')))/length(patch.needle)<>1 then
      raise exception 'occurrence_entry_consumer_drift: %',patch.signature; end if;
    execute replace(definition,patch.needle,patch.replacement);
  end loop;
end $consumers$;

revoke all on function private.exam_use_occurrence_entry_fields_v1(),private.exam_use_occurrence_entry_candidates_v1(jsonb),
  private.exam_use_occurrence_entry_reference_v1(jsonb),private.restore_exam_use_occurrence_v1(jsonb),
  private.lock_exam_use_occurrences_v1(jsonb,text),private.list_exam_use_occurrence_candidates_v1(text,uuid),
  private.prepare_exam_use_occurrence_archive_v1(jsonb,text),private.guard_exam_use_occurrence_write_v1(),
  private.apply_exam_use_occurrence_archive_v1(uuid,text,text,text,jsonb) from public,anon,authenticated,service_role;
notify pgrst,'reload schema';

select set_config('search_path','public',true);
-- APP-20261003-07: share identical reviewed evidence; install tools without changing source rows.
create table private.reviewed_evidence_objects (
  sha256 text primary key check(sha256 ~ '^[a-f0-9]{64}$'),
  evidence jsonb not null check(jsonb_typeof(evidence)='object'),
  check(sha256=private.reviewed_bundle_row_sha256_v1(evidence))
);
create table private.reviewed_resource_archives (
  release_id uuid not null, source_row integer not null,
  target_project_ref text not null,
  original_sha256 text not null check(original_sha256 ~ '^[a-f0-9]{64}$'),
  identity_sha256 text not null check(identity_sha256 ~ '^[a-f0-9]{64}$'),
  entry_sha256 text not null check(entry_sha256 ~ '^[a-f0-9]{64}$'),
  reference_sha256 text not null check(reference_sha256 ~ '^[a-f0-9]{64}$'),
  evidence_hashes text[] not null check(cardinality(evidence_hashes)>0),
  original_bytes integer not null check(original_bytes between 1 and 1048576),
  state text not null check(state in ('prepared','compacted','restored')),
  created_at timestamptz not null default clock_timestamp(),
  primary key(release_id,source_row),
  foreign key(release_id,source_row) references private.reviewed_mock_source_resources_v1(release_id,source_row)
);
create table private.reviewed_resource_archive_receipts (
  request_id uuid primary key,
  request_sha256 text not null check(request_sha256 ~ '^[a-f0-9]{64}$'),
  archive_sha256 text not null check(archive_sha256 ~ '^[a-f0-9]{64}$'),
  result jsonb not null, created_at timestamptz not null default clock_timestamp()
);
create table private.reviewed_resource_write_permits (
  backend_pid integer not null, transaction_id bigint not null,
  release_id uuid not null, source_row integer not null,
  before_sha256 text not null, after_sha256 text not null,
  primary key(backend_pid,transaction_id,release_id,source_row)
);
alter table private.reviewed_evidence_objects enable row level security;
alter table private.reviewed_resource_archives enable row level security;
alter table private.reviewed_resource_archive_receipts enable row level security;
alter table private.reviewed_resource_write_permits enable row level security;
revoke all on private.reviewed_evidence_objects,private.reviewed_resource_archives,private.reviewed_resource_archive_receipts,private.reviewed_resource_write_permits from public,anon,authenticated,service_role;
create trigger reviewed_evidence_object_immutable before update or delete on private.reviewed_evidence_objects
  for each row execute function private.reject_mock_wordbook_history_change();
create trigger reviewed_resource_receipt_immutable before update or delete on private.reviewed_resource_archive_receipts
  for each row execute function private.reject_mock_wordbook_history_change();

-- Fixed locations only: do not recursively rewrite arbitrary future fields.
create function private.reviewed_resource_evidence_items_v1(p_payload jsonb)
returns table(item_path text[],object_value jsonb) language plpgsql immutable strict set search_path='' as $$
declare field_name text; entry record; review record;
begin
  if jsonb_typeof(p_payload->'source_evidence')='object' then
    item_path:=array['source_evidence'];object_value:=p_payload->'source_evidence';return next;
  end if;
  foreach field_name in array array['dictionary','pos','pronunciation','definition','example'] loop
    if jsonb_typeof(p_payload#>array[field_name,'evidence'])='array' then
      for entry in select value,ordinality from jsonb_array_elements(p_payload#>array[field_name,'evidence']) with ordinality loop
        if jsonb_typeof(entry.value)='object' then
          item_path:=array[field_name,'evidence',(entry.ordinality-1)::text];object_value:=entry.value;return next;
        end if;
      end loop;
    end if;
  end loop;
  if jsonb_typeof(p_payload->'review_records')='array' then
    for review in select value,ordinality from jsonb_array_elements(p_payload->'review_records') with ordinality loop
      if jsonb_typeof(review.value->'evidence')='array' then
        for entry in select value,ordinality from jsonb_array_elements(review.value->'evidence') with ordinality loop
          if jsonb_typeof(entry.value)='object' then
            item_path:=array['review_records',(review.ordinality-1)::text,'evidence',(entry.ordinality-1)::text];object_value:=entry.value;return next;
          end if;
        end loop;
      end if;
    end loop;
  end if;
end $$;

create function private.reviewed_resource_shared_hashes_v1(p_rows jsonb) returns text[]
language plpgsql stable strict set search_path='' as $$
declare result text[];
begin
  if exists(select 1 from jsonb_array_elements(p_rows) r cross join lateral private.reviewed_resource_evidence_items_v1(r->'payload') i
    left join private.reviewed_evidence_objects e on e.sha256=private.reviewed_bundle_row_sha256_v1(i.object_value)
    where i.object_value ? '__evidence_ref_v1' or (e.sha256 is not null and e.evidence::text<>i.object_value::text)) then
    raise exception 'reviewed_resource_evidence_collision' using errcode='40001'; end if;
  if exists(select 1 from jsonb_array_elements(p_rows) r cross join lateral private.reviewed_resource_evidence_items_v1(r->'payload') i
    group by private.reviewed_bundle_row_sha256_v1(i.object_value) having count(distinct i.object_value::text)>1) then
    raise exception 'reviewed_resource_evidence_collision' using errcode='40001'; end if;
  with objects as (
    select r.ordinality row_no,i.object_value,private.reviewed_bundle_row_sha256_v1(i.object_value) sha
    from jsonb_array_elements(p_rows) with ordinality r(value,ordinality)
    cross join lateral private.reviewed_resource_evidence_items_v1(r.value->'payload') i
  ), grouped as (
    select sha,min(object_value::text) body,count(*) uses,count(distinct row_no) row_count from objects group by sha
  ) select coalesce(array_agg(g.sha order by g.sha),'{}') into result from grouped g
    left join private.reviewed_evidence_objects e on e.sha256=g.sha
    where (g.uses>=2 or e.sha256 is not null)
      and g.uses*(octet_length(g.body)-octet_length(jsonb_build_object('__evidence_ref_v1',g.sha)::text))
        > g.row_count*192 + case when e.sha256 is null then octet_length(g.body)+256 else 0 end;
  return result;
end $$;

create function private.reviewed_resource_reference_v1(p_row jsonb,p_hashes text[]) returns jsonb
language plpgsql immutable strict set search_path='' as $$
declare payload jsonb:=p_row->'payload'; item record; sha text; seen text[]:='{}'; result jsonb;
begin
  if jsonb_typeof(payload) is distinct from 'object' or payload ? '__reviewed_resource_ref_v1' or cardinality(p_hashes)=0
    or cardinality(p_hashes)<>(select count(distinct h) from unnest(p_hashes) h) then
    raise exception 'reviewed_resource_original_invalid' using errcode='22023'; end if;
  for item in select * from private.reviewed_resource_evidence_items_v1(payload) loop
    if item.object_value ? '__evidence_ref_v1' then raise exception 'reviewed_resource_reserved_marker' using errcode='22023'; end if;
    sha:=private.reviewed_bundle_row_sha256_v1(item.object_value);
    if sha=any(p_hashes) then
      payload:=jsonb_set(payload,item.item_path,jsonb_build_object('__evidence_ref_v1',sha));
      if not(sha=any(seen)) then seen:=array_append(seen,sha); end if;
    end if;
  end loop;
  if not(p_hashes <@ seen) then raise exception 'reviewed_resource_hash_not_in_row' using errcode='22023'; end if;
  result:=jsonb_build_object('__reviewed_resource_ref_v1',payload);
  if octet_length((p_row->'payload')::text)-octet_length(result::text)<=256+64*cardinality(p_hashes) then
    raise exception 'reviewed_resource_not_smaller: %/%',p_row->>'release_id',p_row->>'source_row' using errcode='22023'; end if;
  return result;
end $$;

create function private.restore_reviewed_resource_v1(p_row jsonb) returns jsonb
language plpgsql stable strict set search_path='' as $$
declare stored jsonb:=p_row->'payload'; m private.reviewed_resource_archives; payload jsonb; item record;
  sha text; seen text[]:='{}'; object jsonb; original jsonb;
begin
  select * into m from private.reviewed_resource_archives where release_id=(p_row->>'release_id')::uuid and source_row=(p_row->>'source_row')::integer;
  if not(stored ? '__reviewed_resource_ref_v1') then
    if m.state='compacted' then raise exception 'reviewed_resource_reference_changed' using errcode='40001'; end if;
    return p_row;
  end if;
  if m.release_id is null or m.state<>'compacted'
    or private.reviewed_bundle_row_sha256_v1(p_row-'payload') is distinct from m.identity_sha256
    or private.reviewed_bundle_row_sha256_v1(stored) is distinct from m.reference_sha256 then
    raise exception 'reviewed_resource_reference_changed' using errcode='40001'; end if;
  payload:=stored->'__reviewed_resource_ref_v1';
  for item in select * from private.reviewed_resource_evidence_items_v1(payload) loop
    if item.object_value ? '__evidence_ref_v1' then
      sha:=item.object_value->>'__evidence_ref_v1';
      if item.object_value-'__evidence_ref_v1'<>'{}' or sha !~ '^[a-f0-9]{64}$' or not(sha=any(m.evidence_hashes)) then
        raise exception 'reviewed_resource_reference_invalid' using errcode='40001'; end if;
      select evidence into object from private.reviewed_evidence_objects where sha256=sha;
      if not found or private.reviewed_bundle_row_sha256_v1(object) is distinct from sha then
        raise exception 'reviewed_resource_evidence_missing' using errcode='40001'; end if;
      payload:=jsonb_set(payload,item.item_path,object);seen:=array_append(seen,sha);
    end if;
  end loop;
  original:=jsonb_set(p_row,'{payload}',payload);
  if not(m.evidence_hashes <@ seen) or private.reviewed_bundle_row_sha256_v1(payload) is distinct from m.entry_sha256
    or private.reviewed_bundle_row_sha256_v1(original) is distinct from m.original_sha256
    or private.reviewed_bundle_row_sha256_v1(private.reviewed_resource_reference_v1(original,m.evidence_hashes)) is distinct from m.reference_sha256 then
    raise exception 'reviewed_resource_content_changed' using errcode='40001'; end if;
  return original;
end $$;

-- Recheck the actual compact packet, including partial packets. Preparation is not a savings promise.
create function private.install_reviewed_resource_evidence_v1(p_packet jsonb) returns void
language plpgsql set search_path='' as $$
declare p jsonb; original jsonb; reference jsonb; m private.reviewed_resource_archives; item record;
  savings bigint:=0; new_cost bigint:=0; objects jsonb:='{}'; sha text; stored jsonb;
begin
  for p in select value from jsonb_array_elements(p_packet->'rows') loop
    original:=(p->>'beforeText')::jsonb;
    select * into m from private.reviewed_resource_archives where release_id=(p->>'releaseId')::uuid and source_row=(p->>'sourceRow')::int;
    if not found or private.reviewed_bundle_row_sha256_v1(original) is distinct from m.original_sha256 then
      raise exception 'reviewed_resource_archive_changed' using errcode='40001'; end if;
    reference:=private.reviewed_resource_reference_v1(original,m.evidence_hashes);
    if private.reviewed_bundle_row_sha256_v1(reference) is distinct from m.reference_sha256 then
      raise exception 'reviewed_resource_reference_changed' using errcode='40001'; end if;
    if m.state<>'compacted' then
      savings:=savings+octet_length((original->'payload')::text)-octet_length(reference::text)-256-64*cardinality(m.evidence_hashes);
      for item in select * from private.reviewed_resource_evidence_items_v1(original->'payload') loop
        sha:=private.reviewed_bundle_row_sha256_v1(item.object_value);
        if sha=any(m.evidence_hashes) then
          if objects ? sha and (objects->sha)::text<>item.object_value::text then
            raise exception 'reviewed_resource_evidence_collision' using errcode='40001'; end if;
          objects:=objects||jsonb_build_object(sha,item.object_value);
        end if;
      end loop;
    end if;
  end loop;
  for item in select key,value from jsonb_each(objects) order by key loop
    select evidence into stored from private.reviewed_evidence_objects where sha256=item.key;
    if found then
      if stored::text<>item.value::text then raise exception 'reviewed_resource_evidence_collision' using errcode='40001'; end if;
    else new_cost:=new_cost+octet_length(item.value::text)+256;
    end if;
  end loop;
  if savings<=new_cost and objects<>'{}' then raise exception 'reviewed_resource_batch_not_smaller' using errcode='22023'; end if;
  for item in select key,value from jsonb_each(objects) order by key loop
    insert into private.reviewed_evidence_objects(sha256,evidence) values(item.key,item.value) on conflict(sha256) do nothing;
    -- A separate statement gets the committed row under READ COMMITTED after an insert conflict.
    select evidence into stored from private.reviewed_evidence_objects where sha256=item.key;
    if not found or stored::text<>item.value::text then raise exception 'reviewed_resource_evidence_collision' using errcode='40001'; end if;
  end loop;
end $$;

create function private.lock_reviewed_resources_v1(p_keys jsonb,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' as $$
declare item record; result jsonb; key_count integer;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or jsonb_typeof(p_keys) is distinct from 'array' or jsonb_array_length(p_keys) not between 1 and 100
    or exists(select 1 from jsonb_array_elements(p_keys) k where jsonb_typeof(k) is distinct from 'object'
      or not(k ?& array['releaseId','sourceRow']) or k-array['releaseId','sourceRow']<>'{}'
      or jsonb_typeof(k->'releaseId') is distinct from 'string'
      or jsonb_typeof(k->'sourceRow') is distinct from 'number' or k->>'sourceRow' !~ '^[1-9][0-9]{0,8}$') then
    raise exception 'reviewed_resource_keys_invalid' using errcode='22023'; end if;
  key_count:=jsonb_array_length(p_keys);
  if (select count(distinct ((k->>'releaseId')::uuid,(k->>'sourceRow')::integer)) from jsonb_array_elements(p_keys) k)<>key_count then
    raise exception 'reviewed_resource_duplicate_key' using errcode='22023'; end if;
  if (select count(*) from jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer)
    join private.reviewed_mock_source_resources_v1 o on o.release_id=k."releaseId" and o.source_row=k."sourceRow"
    join private.reviewed_mock_source_releases_v1 s on s.release_id=o.release_id
    join private.reviewed_mock_source_approvals_v1 a on a.approval_id=s.approval_id and a.target_project_ref=s.target_project_ref
    where s.target_project_ref=p_target_project_ref and a.package_version=(select package_version from word_index.app_exam_use_release where release_id=s.release_id)
      and a.dataset_key<>'g12-long-reading-2025-exam-scope-v1')<>key_count then
    raise exception 'reviewed_resource_reviewed_source_required' using errcode='P0002'; end if;
  for item in select distinct r.dataset_key,r.dataset_id,r.release_id from word_index.app_exam_use_release r
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=r.release_id
    order by r.dataset_key,r.release_id loop
    if not pg_try_advisory_xact_lock(hashtextextended(item.dataset_key,9129)) then raise exception 'reviewed_resource_busy' using errcode='55P03'; end if;
    perform 1 from public.vocab_datasets where id=item.dataset_id for update nowait;
    perform 1 from word_index.app_exam_use_release where release_id=item.release_id for update nowait;
  end loop;
  perform 1 from private.reviewed_mock_source_resources_v1 o
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=o.release_id and k."sourceRow"=o.source_row
    order by o.release_id,o.source_row for update of o nowait;
  select jsonb_agg(to_jsonb(o) order by o.release_id,o.source_row) into result from private.reviewed_mock_source_resources_v1 o
    join jsonb_to_recordset(p_keys) k("releaseId" uuid,"sourceRow" integer) on k."releaseId"=o.release_id and k."sourceRow"=o.source_row;
  if jsonb_array_length(result) is distinct from key_count then raise exception 'reviewed_resource_row_changed' using errcode='40001'; end if;
  return result;
end $$;

create function private.list_reviewed_resource_candidates_v1(p_target_project_ref text,p_release_id uuid default null) returns jsonb
language plpgsql set search_path='' as $$
declare result jsonb;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$' then raise exception 'reviewed_resource_project_invalid' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('releaseId',o.release_id,'sourceRow',o.source_row) order by o.release_id,o.source_row),'[]') into result
    from private.reviewed_mock_source_resources_v1 o join private.reviewed_mock_source_releases_v1 s on s.release_id=o.release_id
    join word_index.app_exam_use_release r on r.release_id=o.release_id
    left join private.reviewed_resource_archives m on m.release_id=o.release_id and m.source_row=o.source_row
    where s.target_project_ref=p_target_project_ref and (p_release_id is null or o.release_id=p_release_id)
      and r.dataset_key<>'g12-long-reading-2025-exam-scope-v1' and (m.release_id is null or m.state<>'compacted');
  return result;
end $$;

create function private.prepare_reviewed_resource_archive_v1(p_keys jsonb,p_target_project_ref text) returns jsonb
language plpgsql set search_path='' as $$
declare rows jsonb; row_doc jsonb; original_text text; reference jsonb; m private.reviewed_resource_archives; packets jsonb:='[]'; answer jsonb; all_hashes text[]; row_hashes text[];
begin
  rows:=private.lock_reviewed_resources_v1(p_keys,p_target_project_ref);
  if exists(select 1 from jsonb_array_elements(rows) r join private.reviewed_resource_archives a
    on a.release_id=(r->>'release_id')::uuid and a.source_row=(r->>'source_row')::int where a.state='compacted') then
    raise exception 'reviewed_resource_archive_file_required' using errcode='22023'; end if;
  all_hashes:=private.reviewed_resource_shared_hashes_v1(rows);
  for row_doc in select value from jsonb_array_elements(rows) loop
    select * into m from private.reviewed_resource_archives where release_id=(row_doc->>'release_id')::uuid and source_row=(row_doc->>'source_row')::int for update nowait;
    original_text:=row_doc::text;
    if found then
      if m.target_project_ref<>p_target_project_ref then raise exception 'reviewed_resource_project_mismatch' using errcode='22023'; end if;
      if m.state='compacted' then raise exception 'reviewed_resource_archive_file_required' using errcode='22023'; end if;
      if private.reviewed_bundle_row_sha256_v1(row_doc) is distinct from m.original_sha256 then raise exception 'reviewed_resource_row_changed' using errcode='40001'; end if;
    else
      if octet_length(original_text)>1048576 then raise exception 'reviewed_resource_row_too_large' using errcode='22023'; end if;
      select coalesce(array_agg(distinct private.reviewed_bundle_row_sha256_v1(object_value) order by private.reviewed_bundle_row_sha256_v1(object_value)),'{}') into row_hashes
        from private.reviewed_resource_evidence_items_v1(row_doc->'payload') where private.reviewed_bundle_row_sha256_v1(object_value)=any(all_hashes);
      if cardinality(row_hashes)=0 then raise exception 'reviewed_resource_not_smaller: %/%',row_doc->>'release_id',row_doc->>'source_row' using errcode='22023'; end if;
      reference:=private.reviewed_resource_reference_v1(row_doc,row_hashes);
      insert into private.reviewed_resource_archives(release_id,source_row,target_project_ref,original_sha256,identity_sha256,entry_sha256,reference_sha256,evidence_hashes,original_bytes,state)
      values((row_doc->>'release_id')::uuid,(row_doc->>'source_row')::int,p_target_project_ref,
        private.reviewed_bundle_row_sha256_v1(row_doc),private.reviewed_bundle_row_sha256_v1(row_doc-'payload'),
        private.reviewed_bundle_row_sha256_v1(row_doc->'payload'),private.reviewed_bundle_row_sha256_v1(reference),row_hashes,octet_length(original_text),'prepared');
    end if;
    packets:=packets||jsonb_build_array(jsonb_build_object('releaseId',row_doc->'release_id','sourceRow',row_doc->'source_row','beforeText',original_text));
  end loop;
  answer:=jsonb_build_object('projectRef',p_target_project_ref,'rows',packets);
  if octet_length(answer::text)>16777216 then raise exception 'reviewed_resource_batch_too_large' using errcode='22023'; end if;
  return answer;
end $$;

create function private.guard_reviewed_resource_write_v1() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if tg_op='INSERT' then
    if new.payload ? '__reviewed_resource_ref_v1' or exists(select 1 from private.reviewed_resource_evidence_items_v1(new.payload) where object_value ? '__evidence_ref_v1') then
      raise exception 'reviewed_resource_reserved_marker' using errcode='22023'; end if;
    return new;
  end if;
  if tg_op='UPDATE' and to_jsonb(new)-'payload'=to_jsonb(old)-'payload' then
    delete from private.reviewed_resource_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current()
      and release_id=old.release_id and source_row=old.source_row
      and before_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(old)) and after_sha256=private.reviewed_bundle_row_sha256_v1(to_jsonb(new));
    if found then return new; end if;
  end if;
  raise exception 'reviewed_mock_source_immutable';
end $$;
do $$begin
  if exists(select 1 from private.reviewed_mock_source_resources_v1 r where r.payload ? '__reviewed_resource_ref_v1'
    or exists(select 1 from private.reviewed_resource_evidence_items_v1(r.payload) where object_value ? '__evidence_ref_v1')) then
    raise exception 'reviewed_resource_reserved_marker_exists'; end if;
end $$;
drop trigger reviewed_mock_resource_immutable on private.reviewed_mock_source_resources_v1;
create trigger reviewed_mock_resource_immutable before insert or update or delete on private.reviewed_mock_source_resources_v1
  for each row execute function private.guard_reviewed_resource_write_v1();
create function private.apply_reviewed_resource_archive_v1(p_request_id uuid,p_action text,p_target_project_ref text,p_archive_sha256 text,p_packet jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare request_hash text; receipt private.reviewed_resource_archive_receipts; keys jsonb; locked_rows jsonb; packet_row jsonb;
  original jsonb; current_doc jsonb; next_doc jsonb; reference jsonb; m private.reviewed_resource_archives; result jsonb; changed integer:=0;
begin
  perform private.check_reviewed_bundle_operator_v1();
  if p_request_id is null or p_action is null or p_action not in ('compact','restore')
    or p_target_project_ref is null or p_target_project_ref !~ '^[a-z0-9]{20}$'
    or p_archive_sha256 is null or p_archive_sha256 !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_packet) is distinct from 'object' or not(p_packet ?& array['projectRef','rows']) or p_packet-array['projectRef','rows']<>'{}'
    or p_packet->>'projectRef' is distinct from p_target_project_ref
    or jsonb_typeof(p_packet->'rows') is distinct from 'array' or jsonb_array_length(p_packet->'rows') not between 1 and 100
    or octet_length(p_packet::text)>16777216 or exists(select 1 from jsonb_array_elements(p_packet->'rows') x where jsonb_typeof(x) is distinct from 'object'
      or not(x ?& array['releaseId','sourceRow','beforeText']) or x-array['releaseId','sourceRow','beforeText']<>'{}'
      or jsonb_typeof(x->'beforeText') is distinct from 'string' or octet_length(x->>'beforeText')>1048576) then
    raise exception 'reviewed_resource_packet_invalid' using errcode='22023'; end if;
  request_hash:=private.reviewed_bundle_row_sha256_v1(jsonb_build_array(p_action,p_target_project_ref,p_archive_sha256,p_packet));
  select * into receipt from private.reviewed_resource_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'reviewed_resource_request_reused' using errcode='40001'; end if;return receipt.result;
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('reviewed-resource-request:'||p_request_id,64007)) then raise exception 'reviewed_resource_busy' using errcode='55P03'; end if;
  select jsonb_agg(x-'beforeText') into keys from jsonb_array_elements(p_packet->'rows') x;
  locked_rows:=private.lock_reviewed_resources_v1(keys,p_target_project_ref);
  select * into receipt from private.reviewed_resource_archive_receipts where request_id=p_request_id;
  if found then
    if receipt.request_sha256<>request_hash then raise exception 'reviewed_resource_request_reused' using errcode='40001'; end if;return receipt.result;
  end if;
  if p_action='compact' then perform private.install_reviewed_resource_evidence_v1(p_packet); end if;
  for packet_row in select x from jsonb_array_elements(p_packet->'rows') x order by (x->>'releaseId')::uuid,(x->>'sourceRow')::int loop
    original:=(packet_row->>'beforeText')::jsonb;
    select * into m from private.reviewed_resource_archives where release_id=(packet_row->>'releaseId')::uuid and source_row=(packet_row->>'sourceRow')::int for update nowait;
    if not found then raise exception 'reviewed_resource_preparation_missing' using errcode='P0002'; end if;
    if m.target_project_ref<>p_target_project_ref or original->>'release_id' is distinct from m.release_id::text
      or (original->>'source_row')::int is distinct from m.source_row
      or private.reviewed_bundle_row_sha256_v1(original) is distinct from m.original_sha256
      or private.reviewed_bundle_row_sha256_v1(original->'payload') is distinct from m.entry_sha256 then
      raise exception 'reviewed_resource_archive_changed' using errcode='40001'; end if;
    select d into current_doc from jsonb_array_elements(locked_rows) d where d->>'release_id'=m.release_id::text and (d->>'source_row')::int=m.source_row;
    if private.reviewed_bundle_row_sha256_v1(current_doc-'payload') is distinct from m.identity_sha256
      or private.reviewed_bundle_row_sha256_v1(current_doc->'payload') is distinct from
        (case when m.state='compacted' then m.reference_sha256 else m.entry_sha256 end) then
      raise exception 'reviewed_resource_row_changed' using errcode='40001'; end if;
    reference:=private.reviewed_resource_reference_v1(original,m.evidence_hashes);
    if private.reviewed_bundle_row_sha256_v1(reference) is distinct from m.reference_sha256 then raise exception 'reviewed_resource_reference_changed' using errcode='40001'; end if;
    next_doc:=jsonb_set(current_doc,'{payload}',case when p_action='compact' then reference else original->'payload' end);
    if current_doc is distinct from next_doc then
      insert into private.reviewed_resource_write_permits(backend_pid,transaction_id,release_id,source_row,before_sha256,after_sha256)
      values(pg_backend_pid(),txid_current(),m.release_id,m.source_row,private.reviewed_bundle_row_sha256_v1(current_doc),private.reviewed_bundle_row_sha256_v1(next_doc));
      update private.reviewed_mock_source_resources_v1 set payload=next_doc->'payload' where release_id=m.release_id and source_row=m.source_row;
      if exists(select 1 from private.reviewed_resource_write_permits where backend_pid=pg_backend_pid() and transaction_id=txid_current() and release_id=m.release_id and source_row=m.source_row) then
        raise exception 'reviewed_resource_permit_not_consumed' using errcode='40001'; end if;
      changed:=changed+1;
    end if;
    update private.reviewed_resource_archives set state=case when p_action='compact' then 'compacted' else 'restored' end where release_id=m.release_id and source_row=m.source_row;
    select to_jsonb(o) into current_doc from private.reviewed_mock_source_resources_v1 o where release_id=m.release_id and source_row=m.source_row;
    if private.reviewed_bundle_row_sha256_v1(current_doc) is distinct from private.reviewed_bundle_row_sha256_v1(next_doc)
      or private.reviewed_bundle_row_sha256_v1(private.restore_reviewed_resource_v1(current_doc)) is distinct from m.original_sha256 then
      raise exception 'reviewed_resource_roundtrip_failed' using errcode='40001'; end if;
  end loop;
  result:=jsonb_build_object('requestId',p_request_id,'action',p_action,'rows',jsonb_array_length(p_packet->'rows'),'changed',changed,'archiveHash',p_archive_sha256,'keysHash',private.reviewed_bundle_row_sha256_v1(keys));
  insert into private.reviewed_resource_archive_receipts(request_id,request_sha256,archive_sha256,result) values(p_request_id,request_hash,p_archive_sha256,result);
  return result;
end $$;

-- Patch exactly one payload read and preserve the RPC's OID, ACL, settings and retired-source behavior.
do $consumer$
declare definition text; needle text:='select x.vocab_entry_id,x.payload from private.reviewed_mock_source_resources_v1 x';
begin
  definition:=pg_get_functiondef('public.list_reviewed_mock_source_resources_v1(bigint[])'::regprocedure);
  if (length(definition)-length(replace(definition,needle,'')))/length(needle)<>1 then raise exception 'reviewed_resource_consumer_drift'; end if;
  execute replace(definition,needle,'select x.vocab_entry_id,private.restore_reviewed_resource_v1(to_jsonb(x))->''payload'' from private.reviewed_mock_source_resources_v1 x');
end $consumer$;
revoke all on function private.reviewed_resource_evidence_items_v1(jsonb),private.reviewed_resource_shared_hashes_v1(jsonb),
  private.reviewed_resource_reference_v1(jsonb,text[]),private.restore_reviewed_resource_v1(jsonb),
  private.install_reviewed_resource_evidence_v1(jsonb),private.lock_reviewed_resources_v1(jsonb,text),
  private.list_reviewed_resource_candidates_v1(text,uuid),private.prepare_reviewed_resource_archive_v1(jsonb,text),
  private.guard_reviewed_resource_write_v1(),private.apply_reviewed_resource_archive_v1(uuid,text,text,text,jsonb)
  from public,anon,authenticated,service_role;
