-- APP-20261004-01: extract only the latest included keys once per search.
-- Preserve the exact classification and occurrence membership semantics.
create temporary table app13_search_meta on commit drop as
select to_jsonb(p)-'prosrc' value from pg_proc p
where p.oid='private.vocabulary_library_template_search_v1(private.vocabulary_library_templates)'::regprocedure;
do $guard$
begin
 if not exists (select 1 from pg_proc p where p.oid='private.vocabulary_library_template_search_v1(private.vocabulary_library_templates)'::regprocedure
   and md5(replace(p.prosrc,E'\r\n',E'\n')) in ('e841349184a4aaec37cd48e1f9474f83','31d96ce16e409440078f0bbecc4ee4eb')) then
  raise exception 'unexpected_template_search_body' using errcode='55000';
 end if;
end;
$guard$;
create or replace function private.vocabulary_library_template_search_v1(p_template private.vocabulary_library_templates)
returns text language sql stable security definer set search_path=public,private,pg_temp as $$
 select lower(concat_ws(' ',p_template.metadata->>'title',p_template.metadata->>'tags',p_template.metadata->>'school',
   p_template.metadata->>'targetGrade',p_template.metadata->>'schoolYear',(p_template.metadata->>'semester')||'학기',
   p_template.metadata->>'assessment',p_template.metadata->>'purpose',(
     with latest as materialized (
       select recipe,fixed_composition->'includedKeys' included_keys from private.vocabulary_library_versions
       where template_id=p_template.id order by number desc limit 1
     ) select string_agg(concat_ws(' ',
       case c->>'kind' when 'mock' then '모의고사 모고' when 'csat' then '수능' when 'textbook' then '교과서' when 'wordbook' then '단어장' when 'school' then '학교 자료' else '분류 확인' end,
       case c->>'sourceGrade' when 'g7' then '중1' when 'g8' then '중2' when 'g9' then '중3' when 'g10' then '고1' when 'g11' then '고2' when 'g12' then '고3' end,
       (c#>>'{exam,executionYear}')||'년',case when c->>'kind'='mock' then (c#>>'{exam,examMonth}')||'월' end,
       case when c->>'kind'='csat' then (c#>>'{exam,academicYear}')||'학년도' end,c#>>'{exam,typeLabel}',
       'DAY '||(c->>'day'),(c->>'lesson')||'과'),' ')
     from latest v
     cross join lateral jsonb_array_elements(v.recipe->'scopes') ref
     join private.vocabulary_library_scopes s on s.id=(ref->>'id')::uuid and s.version=ref->>'version'
     cross join lateral (select s.payload->'classification' c) classification
     where exists(select 1 from private.vocabulary_library_scope_rows r where r.scope_id=s.id and v.included_keys ? r.occurrence_key)
   )))
$$;
do $verify$
begin
 if not exists (select 1 from app13_search_meta) or not exists (
   select 1 from pg_proc p where p.oid='private.vocabulary_library_template_search_v1(private.vocabulary_library_templates)'::regprocedure
    and (to_jsonb(p)-'prosrc')=(select value from app13_search_meta)
 ) then raise exception 'template_search_metadata_changed' using errcode='55000'; end if;
end;
$verify$;

set local search_path=public;
do $guard$
declare t record;old_fn record;new_fn record;a record;cols text;cnt bigint;h text;expected jsonb;actual jsonb;
begin
 if exists(select 1 from m10_original_table_security b left join pg_class c on c.oid=b.oid where c.oid is null or c.relrowsecurity is distinct from b.relrowsecurity or c.relforcerowsecurity is distinct from b.relforcerowsecurity or c.relacl is distinct from b.relacl or c.relowner is distinct from b.relowner) then raise exception 'm10_table_security_changed';end if;
 for t in select c.*,b.row_count,b.content_hash from m10_columns c join m10_hashes b on b.table_oid=c.oid loop
  if to_regclass(format('%I.%I',t.schema,t.name))::oid is distinct from t.oid then raise exception 'm10_original_table_changed: %.%',t.schema,t.name;end if;
  select string_agg(format('t.%I',x),',' order by n) into cols from unnest(t.columns) with ordinality as u(x,n);
  execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from (select md5(to_jsonb(r)::text) h from (select %s from %I.%I t)r)s',cols,t.schema,t.name) into cnt,h;
  if cnt<>t.row_count or h is distinct from t.content_hash then raise exception 'm10_original_data_changed: %.%',t.schema,t.name;end if;
 end loop;
 for old_fn in select * from m10_old_functions loop
  select * into a from m10_allowed_functions x where x.schema=old_fn.schema and x.name=old_fn.name and x.args=old_fn.args;
  expected:=old_fn.metadata;
  if found then
   expected:=expected||jsonb_build_object('prosrc',(select prosrc from pg_proc where oid=old_fn.oid),'prolang',(select oid from pg_language where lanname=a.new_language),'prosecdef',a.new_security,'provolatile',a.new_volatility);
   if md5((select prosrc from pg_proc where oid=old_fn.oid)) is distinct from a.new_hash then raise exception 'm10_function_body_mismatch: %.%',old_fn.schema,old_fn.name;end if;
  end if;
  select to_jsonb(f) into actual from pg_proc f where f.oid=old_fn.oid;
  if actual is distinct from expected then raise exception 'm10_function_metadata_changed: %.%',old_fn.schema,old_fn.name;end if;
 end loop;
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','word_index') and not exists(select 1 from m10_old_functions b where b.oid=p.oid))<>237 then raise exception 'm10_new_function_count';end if;
 for a in select * from m10_added_functions loop
  select p.*,l.lanname language into new_fn from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname=a.schema and p.proname=a.name and pg_get_function_identity_arguments(p.oid)=a.args;
  if not found or (md5(new_fn.prosrc)=any(a.body_md5s)) is distinct from true or new_fn.language<>a.language or new_fn.prosecdef<>a.security_definer or new_fn.provolatile<>a.volatility or new_fn.proacl::text is distinct from a.acl or to_jsonb(new_fn.proconfig) is distinct from a.config or pg_get_function_result(new_fn.oid)<>a.result then raise exception 'm10_new_function_contract: %.%',a.schema,a.name;end if;
 end loop;
 for a in select * from jsonb_to_recordset('[{"schema":"private","name":"student_word_practice_questions","column":"content_version_id"},{"schema":"private","name":"vocabulary_library_templates","column":"template_kind"},{"schema":"public","name":"assignment_question_exam_use_snapshot","column":"content_version_id"},{"schema":"public","name":"assignment_questions","column":"content_version_id"},{"schema":"public","name":"assignment_review_targets","column":"meaning_key_snapshot"},{"schema":"public","name":"assignment_review_targets","column":"mistake_episode_id"},{"schema":"public","name":"quiz_questions","column":"content_version_id"},{"schema":"public","name":"student_vocab_review_queue","column":"meaning_key_snapshot"},{"schema":"public","name":"student_vocab_review_queue","column":"mistake_episode_id"},{"schema":"public","name":"student_vocab_review_queue","column":"source_phase_snapshot"}]'::jsonb) as x(schema text,name text,column_name text,"column" text) loop
