  if not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=t.schema and c.relname=t.name and c.relrowsecurity=t.rls and c.relforcerowsecurity=t.force_rls and c.relacl::text is not distinct from t.acl and pg_get_userbyid(c.relowner)=t.owner) then raise exception 'm10_new_table_security: %.%',t.schema,t.name;end if;
  if t.name='operational_retention_policy' then
   if (select count(*) from private.operational_retention_policy)<>1 or (select to_jsonb(p)-'changed_at'-'changed_by' from private.operational_retention_policy p) is distinct from '{"singleton":true,"version":1,"success_days":7,"failure_days":30,"session_days":7,"login_hours":24,"preparation_hours":24}'::jsonb then raise exception 'm10_retention_defaults';end if;
